// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Türk ve dünya tiyatro edebiyatı: trajedi, komedi, dram ve çağdaş oyun yazarları (Sofokles, Shakespeare, Molière, İbsen, Çehov, Brecht, Haldun Taner) (zor).
const ozLiterature16Zor = <(String, String, List<String>, String)>[
  ('Varlıklı Atina yurttaşlarının kamu hizmeti (leitourgia) kapsamında bir tiyatro korosunun tüm masraflarını, kostümlerini ve eğitim giderlerini üstlenmesine verilen unvan nedir?', 'Khoregos', ['Strategos', 'Theorodokos', 'Paidagogos'], 'Antik Atina\'da koro giderlerini finanse eden zengin yurttaşlara khoregos denir; yarışmayı kazanan oyunlarda şeref payını şairle paylaşırlardı.'),
  ('Antik Yunan sahnesinde şiddet ve cinayet eylemleri seyirci önünde gösterilmediği için, içeride işlenen kanlı olayın sonucunu (cesetleri) dışarıya iten tekerlekli platforma ne denirdi?', 'Ekkyklema', ['Kothurnos', 'Thymele', 'Diazoma'], 'Ekkyklema, skene kapısından dışarı sürülen tekerlekli veya döner kürsü olup Agamemnon ya da Antigone gibi oyunlarda içerideki cesetleri görünür kılardı.'),
  ('Günümüze metni eksiksiz ulaşabilmiş tek Antik Yunan satir oyunu olan ve Odysseus\'un tek gözlü dev Polyphemos\'un mağarasından kurtuluşunu işleyen Kyklops kimin eseridir?', 'Euripides', ['Sofokles', 'Aiskhylos', 'Agathon'], 'Sofokles\'in İzsürücüler adlı satir oyununun yalnızca parçaları kalmışken, Euripides\'in Kyklops adlı yapıtı tam metin halinde günümüze ulaşan tek örnektir.'),
  ('Aşil\'in silahlarının kendisine değil de kurnaz Odysseus\'a verilmesini onuruna yediremeyip çıldırarak ordu komutanları sanısıyla koyun sürülerini doğrayan savaşçının yıkımını hangi Sofokles eseri anlatır?', 'Aias', ['Rhesos', 'Hekabe', 'İon'], 'Sofokles\'in günümüze kalan en erken tarihli oyunu kabul edilen Aias, eski kahramanlık ahlakını temsil eden savaşçının utanç karşısında intiharını işler.'),
  ('Yılan ısırığı yüzünden kokan yarası nedeniyle ıssız Lemnos Adası\'na terk edilen okçunun elindeki Herakles yayını almak için Odysseus ile genç Neoptolemos\'un kurduğu hileyi konu edinen oyun hangisidir?', 'Philoktetes', ['Phoinissai', 'Hippolytos', 'Orestes'], 'Sofokles\'in Philoktetes oyununda politik çıkarcılık (Odysseus) ile genç Neoptolemos\'un dürüstlük vicdanı çarpışır; düğümü sahneye inen Herakles çözer.'),
  ('Klasik dönem sonrası Fransız tiyatrosunun Poetika\'yı katı biçimde yorumlayarak kurallaştırdığı \'üç birlik kuralı\' kapsamında Aristoteles\'in özgün metninde aslında en açık biçimde vurguladığı birlik hangisidir?', 'Eylem (olay) birliği', ['Dekor (mekân) birliği', 'Perde sayısı birliği', 'Karakter zümresi birliği'], 'Aristoteles Poetika\'da temel ilke olarak eylem birliğini şart koşmuş, zaman için yalnızca \'güneşin bir dönüşü kadar\' gözleminde bulunmuş, mekân birliği kuralı ise Rönesans\'ta türetilmiştir.'),
  ('Eski Komedya yapısında oyuncuların sahneden çekildiği, koronun maskelerini çıkarıp doğrudan seyirciye dönerek şairin politik ve toplumsal görüşlerini dile getirdiği bölüme ne ad verilir?', 'Parabasis', ['Prologos', 'Epeisodion', 'Anagnorisis'], 'Parabasis (\'öne yürüme\'), Eski Komedya\'ya özgü bir ara bölüm olup dramatik yanılsamayı bilerek kırar ve koroyu şairin doğrudan sözcüsü yapar.'),
  ('1950\'li yıllarda Mısır\'da bulunan Bodmer Papirüsü sayesinde tam metni gün ışığına çıkan ve insanlardan nefret edip kırsalda tek başına yaşayan Knemon karakterini işleyen Menandros komedyası hangisidir?', 'Dyskolos (Huysuz Adam)', ['Perikeiromene (Saçı Kesilen Kız)', 'Samia (Sisamlı Kadın)', 'Epitrepontes (Hakeme Başvuranlar)'], 'Menandros\'un yüzü aşkın oyunundan eksiksiz ele geçen tek yapıtı olan Dyskolos, kuyuya düşüp üvey oğlu tarafından kurtarılan aksi ihtiyarın yumuşamasını anlatır.'),
  ('MÖ 240 yılında Roma Oyunları (Ludi Romani) sırasında Yunancadan Latinceye çevirdiği bir trajedi ve bir komediyi sahneleyerek Latin tiyatro edebiyatını başlattığı kabul edilen Yunan asıllı şair kimdir?', 'Livius Andronicus', ['Quintus Ennius', 'Gnaeus Naevius', 'Marcus Pacuvius'], 'Tarentum\'dan Roma\'ya esir getirilen ve azat edilen Livius Andronicus, Yunan kalıplarını Latinceye uyarlayarak Roma yazılı edebiyatının ve tiyatrosunun öncüsü olmuştur.'),
  ('Roma edebiyatında Yunan Yeni Komedyası örneklerinden uyarlanan, olayların Yunan kentlerinde geçtiği ve oyuncuların Yunan giysisi (pallium) giydiği komedya türüne ne ad verilirdi?', 'Fabula palliata', ['Fabula praetexta', 'Fabula togata', 'Fabula atellana'], 'Plautus ve Terentius\'un yazdığı komedyalar \'fabula palliata\' (Yunan harmanisi giyilen oyun) olarak adlandırılır; Roma yaşamını ve giysisini kullanan yerli komedyaya ise fabula togata denirdi.'),
  ('Tanrı Jüpiter\'in, Tebai komutanının güzel karısı Alcmena ile birlikte olabilmek için kadının kocasının kılığına girmesini, Merkür\'ün de köle Sosia kılığına bürünmesini işleyen ve yazarının \'trajikomedi\' diye nitelediği Plautus oyunu hangisidir?', 'Amphitryon', ['Pseudolus', 'Casina', 'Bacchides'], 'Plautus, Amphitryon\'un önsözünde tanrılarla kralların yanı sıra kölelerin de yer aldığı bu melez türe tarihte ilk kez \'tragico-comoedia\' adını vermiştir.'),
  ('Terentius\'un ilk iki temsilinde halkın ip cambazlarını ve gladyatör dövüşlerini izlemek için tiyatroyu terk etmesi yüzünden yarım kalan, ancak üçüncü denemede tamamlanabilen aile komedyası hangisidir?', 'Kaynana (Hecyra)', ['Androslu Kız (Andria)', 'Kardeşler (Adelphoe)', 'Phormio'], 'Terentius\'un Hecyra (Kaynana) oyununun prologları, Roma\'da ciddi edebi tiyatronun popüler sirk ve gladyatör eğlenceleri karşısında yaşadığı zorluğu belgeleyen değerli bir tanıklıktır.'),
  ('İki erkek kardeşten Demea\'nın sert ve otoriter disiplinini, Micio\'nun ise hoşgörülü ve özgürlükçü yaklaşımını karşılaştırarak gençlerin nasıl yetiştirilmesi gerektiğini tartışan Terentius eseri hangisidir?', 'Kardeşler (Adelphoe)', ['Hadım (Eunuchus)', 'Çömlek (Aulularia)', 'Urgan (Rudens)'], 'Terentius\'un son oyunu Adelphoe (MÖ 160), pedagojik yaklaşımları karşılaştıran yapısıyla Molière\'in Kocalar Mektebi adlı eserine ilham vermiştir.'),
  ('Kardeşi Atreus\'un, iktidar ve ihanet öcü almak amacıyla öz yeğenlerini kesip pişirerek babalarına ziyafet sofrasında yedirmesini tüm dehşetiyle işleyen Seneca trajedisi hangisidir?', 'Thyestes', ['Octavia', 'Phoenissae', 'Troades'], 'Seneca\'nın Thyestes adlı eseri, dizginlenemeyen öfkenin (ira) ve tiranlığın insanı nasıl canavarlaştırdığını gösteren en sarsıcı intikam trajedisidir.'),
  ('Bir Yunan trajedisinde diyalog sahneleri (epeisodion) arasında koronun orkestrada yerini koruyarak söylediği durağan koro şarkılarına hangi isim verilir?', 'Stasimon', ['Eksodos', 'Parabasis', 'Monodia'], 'Epeisodionları birbirinden ayıran, olaylar üzerine felsefi veya dinsel yorum getiren yerleşik koro ezgilerine stasimon denir.'),
  ('İki oyuncunun yüksek duygusal gerilim ya da sert tartışma anlarında karşılıklı olarak birer dizelik hızlı repliklerle atışmasına Yunan dram tekniğinde ne ad verilir?', 'Stikhomythia', ['Parrhesia', 'Deuteragonistes', 'Skenographia'], 'Stikhomythia (\'dize konuşması\'), karakterler arasındaki irade çatışmasını veya sorgulamayı keskinleştiren birer dizelik ritmik diyalog tekniğidir.'),
  ('Yunan tiyatrosundan farklı olarak Roma tiyatro mimarisinde yamaca yaslanma zorunluluğunu ortadan kaldıran kemerli tonoz sistemiyle inşa edilmiş ilk kalıcı taş tiyatro (MÖ 55) kimin adıyla anılır?', 'Pompeius Tiyatrosu', ['Colosseum', 'Circus Maximus', 'Hadrianus Odeonu'], 'Senatonun kalıcı tiyatro yasağını aşmak için üst kısmına Venüs Tapınağı eklenerek inşa edilen Pompeius Tiyatrosu, Roma\'nın ilk taş tiyatrosudur.'),
  ('Atina\'da yalnızca kış ortasında (Ocak-Şubat) kent içinde kutlanan ve özellikle komedya yarışmalarına ağırlık verilen daha yerel Dionysos festivali hangisidir?', 'Lenaia Şenliği', ['İsthmia Oyunları', 'Nemea Şenliği', 'Thesmophoria Bayramı'], 'Deniz ulaşımının kapalı olduğu kış aylarında yabancılardan çok bizzat Atinalıların katıldığı Lenaia festivali, Aristofanes\'in Eşekarıları ve Atlılar gibi komedyalarının sahnelendiği şenliktir.'),
  ('Sofokles\'in Trakhisli Kadınlar oyununda, kocası Herakles\'in sevgisini yeniden kazanmak umuduyla Kentaur Nessos\'un kanına bulanmış gömleği ona gönderip bilmeden ölümüne yol açan talihsiz eş kimdir?', 'Deianeira', ['İokaste', 'Eurydike', 'Megara'], 'Deianeira\'nın aşk iksiri sandığı zehirli gömlekle Herakles\'i yakması, iyi niyetle yapılan eylemin korkunç yıkıma dönüşmesinin (hamartia ve peripeteia) çarpıcı bir örneğidir.'),
  ('Güney İtalya ve İyonya kökenli olup doğaçlama, maskesiz ve kadın oyuncuların da yer alabildiği, gündelik yaşamın gülünç sahnelerini taklit eden kısa halk güldürülerine Antik Çağ\'da ne ad verilirdi?', 'Mimos', ['Dithyrambos', 'Tragoidia', 'Kommos'], 'Resmî şenlik kalıplarının dışında gelişen mimos (mim), kadın ve erkek oyuncuların maskesiz olarak kent yaşamındaki tipleri taklit ettiği gerçekçi halk gösterisidir.'),
  ('Roma İmparatorluğu döneminde sözlü dramanın gerilemesiyle öne çıkan, tek bir maskeli dansçının koro ve orkestra eşliğinde konuşmadan yalnız beden hareketleriyle mitolojik öyküleri canlandırdığı gösteri türü nedir?', 'Pantomimus', ['Fabula crepidata', 'Satura drammatica', 'Ludi scaenici'], 'Augustus çağında Pylades ve Bathyllus tarafından geliştirilen pantomimus, tek bir sanatçının maske değiştirerek tüm rolleri sessiz dansla oynadığı popüler Roma sanatıdır.'),
  ('Aristofanes\'in son oyunu olan ve gözleri görmeyen Servet Tanrısı\'nın görme yetisine kavuşturulmasıyla zenginliğin kötülerin elinden alınıp dürüst insanlara dağıtılmasını işleyen alegorik komedya hangisidir?', 'Plutos', ['Ekklesiazusai', 'Akharnialılar', 'Thesmophoriazusai'], 'MÖ 388\'de sahnelenen Plutos (Servet), koro şarkılarının ve kişisel taşlamanın azaldığı yapısıyla Eski Komedya\'dan Orta Komedya\'ya geçişin en belirgin örneğidir.'),
  ('Atinalı kadınların kocalarının elbiselerini ve takma sakalları kuşanıp şafak vakti Halk Meclisi\'ne sızarak özel mülkiyeti kaldıran ortaklaşacı bir yönetim ilan etmesini anlatan Aristofanes komedyası hangisidir?', 'Kadınlar Meclisi (Ekklesiazusai)', ['Yalvarıcı Kızlar (Hiketides)', 'Troyalı Kadınlar (Troades)', 'Trakhisli Kadınlar (Trakhiniai)'], 'Aristofanes\'in MÖ 392 tarihli Ekklesiazusai adlı eseri, mülkiyet ortaklığı fikrini parodileştirerek Platon\'un Devlet\'indeki tasarımlarla ilginç koşutluklar taşır.'),
  ('Aiskhylos\'un Yalvarıcı Kızlar (Hiketides) oyununda Mısır\'dan kaçıp Argos Kralı Pelasgos\'a sığınan Danaos\'un elli kızının reddettiği zorlama nedir?', 'Amca oğulları olan Aigyptos\'un elli oğluyla zorla evlendirilmek', ['Mısır tapınaklarında köle rahibe olarak ömür boyu çalıştırılmak', 'Nil taşkınlarını durdurmak amacıyla timsahlara kurban edilmek', 'Kardeşleri tarafından çeyiz mirasından bütünüyle mahrum bırakılmak'], 'Yalvarıcı Kızlar\'da Danaos\'un kızları, kuzenleriyle zoraki evlilikten kaçarak Argos meclisinin demokratik kararıyla sığınma hakkı elde ederler.'),
  ('Plautus\'un Hortlak (Mostellaria) adlı komedyasında, efendisi Theopropides seyahatteyken evi eğlence yerine çeviren ve baba ansızın dönünce \'ev perili olduğu için içeri girilemez\' yalanını uyduran kurnaz köle kimdir?', 'Tranio', ['Davos', 'Sosia', 'Euclio'], 'Mostellaria\'da köle Tranio\'nun ayaküstü kurduğu hayaletli ev yalanı ve bunu sürdürmek için girdiği kılıktan kılığa haller, Roma komedyasının en parlak entrikalarındandır.'),
  ('Roma edebiyatında konularını Yunan mitolojisi yerine doğrudan Roma tarihinden (örneğin Romulus veya Brutus\'tan) alan ve oyuncuların mor şeritli Roma senatör giysisi giydiği yerli trajedi türüne ne ad verilirdi?', 'Fabula praetexta', ['Fabula cothurnata', 'Fabula palliata', 'Fabula saltica'], 'Yunan trajedisi uyarlamalarına fabula cothurnata denirken, Gnaeus Naevius\'un başlattığı Roma ulusal tarih konulu trajedilere \'fabula praetexta\' adı verilmiştir.'),
  ('Günümüze tam metni ulaşan tek \'fabula praetexta\' (Roma tarih trajedisi) örneği olup İmparator Neron\'un masum karısını boşayıp sürgüne ve ölüme göndermesini işleyen, uzun süre yanlışlıkla Seneca\'ya mal edilmiş oyun hangisidir?', 'Octavia', ['Lucretia', 'Virginia', 'Cleopatra'], 'Seneca\'nın bizzat bir karakter olarak yer aldığı ve Neron\'un ölümüne dair kehanetler içerdiği için Seneca sonrası dönemde yazıldığı anlaşılan Octavia, türünün tek tam örneğidir.'),
  ('Euripides\'in Hekabe trajedisinde, Troya düştükten sonra sabık kraliçenin son oğlu Polydoros\'u emanet olarak aldığı altınlara konmak için öldüren Trakya Kralı Polymestor\'dan aldığı korkunç intikam nedir?', 'Kralın iki oğlunu öldürüp kendisinin de gözlerini kör etmesi', ['Kralın donanmasını gece yarısı limanda ateşe verip kül etmesi', 'Şölen şarabına zehir katarak tüm Trakya komutanlarını uyutması', 'Kralı Agamemnon\'un çadırında zincirletip Troya surlarından atması'], 'Kızı Polyksena kurban edildikten sonra kıyıda oğlu Polydoros\'un cesedini bulan acılı anne Hekabe, çadırına çektiği açgözlü Polymestor\'u diğer esir kadınlarla birlikte kör eder.'),
  ('Güney İtalya\'daki Osk halkının Atella kasabasından Roma\'ya geçen; Maccus (aptal obur), Bucco (boşboğaz), Pappus (kandırılan ihtiyar) ve Dossennus (kurnaz kambur) adlı dört sabit maskeli tipe dayanan kaba halk güldürüsü nedir?', 'Fabula atellana', ['Fabula praetexta', 'Tragoedia rhetorica', 'Canticum lyrica'], 'Kısa ve doğaçlama oynanan Atellana güldürüsü (fabula atellana), sabit maskeli tipleriyle yüzyıllar sonraki İtalyan Commedia dell\'arte geleneğinin antik öncülerinden sayılır.'),
  ('Aristofanes\'in Barış (Eirene) adlı komedyasında savaş yüzünden bağları harap olan köylü Trygaios, savaş tanrısı Polemos\'un mağaraya hapsettiği Barış Tanrıçası\'nı kurtarmak için Olympos\'a neyin sırtında uçar?', 'Dev bir gübre böceğinin sırtında', ['Kanatlı beyaz at Pegasos\'un sırtında', 'Zeus\'un şimşek taşıyan altın kartalında', 'Rüzgâr tanrısı Aiolos\'un tulum balonunda'], 'Trygaios, Euripides\'in Pegasos\'la göğe çıkan Bellerophontes trajedisini komik biçimde parodileştirerek beslediği dev bir bokböceğine binip tanrıların katına çıkar.'),
  ('Commedia dell\'arte oyuncularının sahnede metinden bağımsız olarak araya sıkıştırdıkları, seyirciyi kahkahaya boğan kalıplaşmış sözlü veya fiziksel soytarılık numaralarına ne ad verilirdi?', 'Lazzi', ['Zanni', 'Innamorati', 'Intermezzi'], 'Örneğin \'sinek yakalama lazzisi\' veya \'açlıktan kendi ayakkabısını yeme lazzisi\' gibi fiziksel-komik ara numaralara Commedia dell\'arte dağarcığında lazzi denirdi.'),
  ('Siyaset biliminin kurucularından Niccolò Machiavelli\'nin 1518 dolaylarında kaleme aldığı, çocuk sahibi olmak isteyen yaşlı hukukçu Nicia\'nın genç karısı Lucrezia\'yı elde etmek için kurulan şifalı ot hilesini anlatan Rönesans komedyası hangisidir?', 'Adamotu (Mandragola)', ['Saraylı (Il Cortegiano)', 'Çılgın Orlando (Orlando Furioso)', 'Prens (Il Principe)'], 'Machiavelli\'nin Mandragola (Adamotu) oyunu, Floransa toplumunun ahlaki ikiyüzlülüğünü ve çıkarcı din adamı Fra Timoteo\'yu keskin gerçekçilikle taşlayan Rönesans başyapıtıdır.'),
  ('Avrupa edebiyatında Molière, Mozart, Byron ve Bernard Shaw gibi pek çok sanatçıya esin veren efsanevi çapkın \'Don Juan\' karakterini Sevilla Çapkını ve Taştan Konuk adlı oyunuyla ilk kez sahneye çıkaran İspanyol yazar kimdir?', 'Tirso de Molina', ['Miguel de Cervantes', 'Fernando de Rojas', 'Francisco de Quevedo'], 'Rahip Gabriel Téllez\'in (Tirso de Molina) 1630\'da yayımlanan El burlador de Sevilla oyunu, öldürdüğü komutanın mezar heykelini yemeğe çağıran Don Juan mitinin ilk edebi metnidir.'),
  ('Venedikli çocuksuz zengin Volpone\'nin uşağı Mosca ile birlikte ölüm döşeğindeymiş numarası yaparak mirasına konmak isteyen açgözlü dalkavukları soyup soğana çevirmesini anlatan \'mizaçlar komedyası\' ustası İngiliz yazar kimdir?', 'Ben Jonson', ['Richard Brinsley Sheridan', 'William Congreve', 'Oliver Goldsmith'], 'Shakespeare\'in çağdaşı ve rakibi Ben Jonson, Volpone ya da Tilki (1606) adlı komedyasında insan açgözlülüğünü hayvan adları taşıyan karakterlerle acımasızca hicveder.'),
  ('Fransız klasik trajedisinin iki dev ismi Pierre Corneille ile Jean Racine\'in insan doğasına yaklaşımları arasındaki temel fark La Bruyère\'den bu yana nasıl özetlenir?', 'Corneille insanları irade gücüyle ödevini seçen kahramanlar olarak, Racine ise tutkularının pençesinde yenilen varlıklar olarak çizer', ['Corneille yalnızca İncil öykülerini işlerken Racine yalnızca Orta Çağ Fransız şövalye destanlarını sahneye taşır', 'Corneille oyunlarını halk argosu ve düzyazıyla yazarken Racine serbest ölçü ve doğaçlama kullanır', 'Corneille üç birlik kuralına harfiyen uyarken Racine sahnede kalabalık savaş ve idam sahneleri gösterir'], 'Corneille\'de irade ve şeref tutkuya üstün gelirken; Jansenist eğitimden geçen Racine\'de (örneğin Phèdre ve Andromaque\'ta) yazgısal aşk ve kıskançlık tutkusu kahramanı yıkıma sürükler.'),
  ('Osmanlı sarayında IV. Murat\'ın Bağdat Seferi sırasında İstanbul\'da kalan Şehzade Bayezid ile Roxane arasındaki iktidar ve aşk entrikasını, \'uzak coğrafya zamansal uzaklığın yerini tutar\' gerekçesiyle işleyen Racine trajedisi hangisidir?', 'Bajazet', ['Mithridate', 'Polyeucte', 'Rodogune'], 'Klasik trajedinin konularını Antik Çağ\'dan seçme kuralını Racine, 1672 tarihli Bajazet oyununda Osmanlı sarayının Fransız seyircisi için Antik Çağ kadar uzak ve görkemli olduğu savıyla aşmıştır.'),
  ('Goldoni\'nin gerçekçi tiyatro reformuna karşı çıkarak Commedia dell\'arte maskelerini Doğu masalları ve büyü ögeleriyle birleştiren; Üç Turunç Aşkı ile Puccini\'nin operasına da kaynaklık eden Turandot masal oyunlarını yazan Venedikli kont kimdir?', 'Carlo Gozzi', ['Torquato Tasso', 'Gabriele D\'Annunzio', 'Ugo Foscolo'], 'Carlo Gozzi, \'fiabe teatrali\' (tiyatro masalları) adını verdiği fantastik oyunlarıyla hem Alman Romantiklerini hem de 20. yüzyılda Meyerhold ve Prokofyev\'i etkilemiştir.'),
  ('Schiller\'in Hile ve Sevgi (Kabale und Liebe) adlı \'burjuva trajedisi\'nde saray entrikaları ve sahte mektup tuzağı yüzünden limonatasına zehir katarak birlikte ölüme giden farklı toplumsal sınıftan iki genç âşık kimdir?', 'Soylu binbaşı Ferdinand ile müzisyen kızı Luise Miller', ['İspanya veliahtı Don Carlos ile üvey annesi Elisabeth', 'İskoçya Kraliçesi Maria Stuart ile Kont Leicester', 'Şövalye Götz von Berlichingen ile saraylı Adelheid'], 'Schiller, Hile ve Sevgi\'de yozlaşmış mutlakiyetçi saray ahlakı ile dürüst kentsoylu (burjuva) ailesi arasındaki uçurumu Ferdinand ve Luise\'nin trajik aşkıyla sergiler.'),
  ('Victor Hugo\'nun Kral I. François\'nın çapkınlıklarına alet olan kambur saray soytarısı Triboulet\'nin öz kızı Blanche\'ı korumak isterken yanlışlıkla çuvalda onu öldürtmesini işlediği ve Verdi\'nin Rigoletto operasına kaynak olan dramı hangisidir?', 'Kral Eğleniyor', ['Ruy Blas', 'Burgrave\'lar', 'Mary Tudor'], 'Hugo\'nun \'grotesk beden içinde yüce babalık sevgisi\' tezini somutlaştırdığı Kral Eğleniyor (1832), krallık makamını aşağıladığı gerekçesiyle ilk temsilinin ertesi günü yasaklanmıştır.'),
  ('Sürgüne gönderilen efendisi Don Salluste\'ün intikam planı gereği sahte kimlikle İspanya sarayına sokulan ve Kraliçe\'ye duyduğu gizli aşkla başbakanlığa dek yükselen bir uşağın trajik sonunu anlatan Victor Hugo dramı hangisidir?', 'Ruy Blas', ['Torquemada', 'Hernani', 'Cromwell'], 'Victor Hugo\'nun 1838 tarihli Ruy Blas dramı, \'bir kraliçeye âşık olan yer solucanı\' metaforuyla halkın içindeki soylu yeteneği ve çürüyen İspanyol monarşisini simgeler.'),
  ('Heinrich von Kleist\'ın 1808 tarihli Kırık Testi (Der zerbrochne Krug) adlı komedyasında, gece yarısı genç Eve\'in odasına gizlice girip kaçarken testiyi kıran suçluyu bulmak üzere mahkemeyi yöneten Köy Yargıcı Adam\'ın durumu Kral Oidipus\'u hangi yönüyle tersinler?', 'Soruşturmayı yürüten yargıcın, başından beri aranan asıl suçlunun bizzat kendisi olduğunu bilip bunu örtbas etmeye çalışmasıyla', ['Suçsuz olduğu halde köy halkını vebadan kurtarmak amacıyla suçu gönüllü olarak kendi üzerine almasıyla', 'Kırılan testinin içinden kayıp kraliyet mührünün çıkması sonucu yargıcın dük ilan edilmesiyle', 'Mahkeme kâtibinin yargıcın çocukken kaybolmuş öz oğlu olduğunun doğum lekesinden anlaşılmasıyla'], 'Kral Oidipus suçlunun kendisi olduğunu bilmeden dürüstçe ararken, Kleist\'ın Kırık Testi komedyasında Yargıç Adam gece pencereden atlarken yaralanan asıl suçlunun kendisi olduğunu bildiği için suçu başkalarına yıkmaya kıvranır.'),
  ('18. yüzyıl Fransız düşünürü Denis Diderot\'nun klasik trajedi ile komedi arasındaki boşluğu doldurmak üzere kuramlaştırdığı, kralları değil kentsoylu ailelerin mesleki ve toplumsal sorumluluklarını düzyazıyla işleyen ara türe ne ad verilmiştir?', 'Burjuva dramı (Ciddi tür / Drame bourgeois)', ['Gözü yaşlı komedya (Comédie larmoyante)', 'Bulvar vodvili (Vaudeville de boulevard)', 'Saray maskeli balosu (Masque de cour)'], 'Diderot, Evlilik Dışı Oğul ve Aile Babası oyunları ile bunlara yazdığı söyleşilerde bireyin karakterinden çok toplumsal \'konum ve mesleğini\' (yargıç, baba, tüccar) merkeze alan burjuva dramını kurmuştur.'),
  ('Diderot\'nun ünlü Aktörlük Üzerine Aykırı Düşünceler (Paradoxe sur le comédien) adlı denemesinde en başarılı tiyatro oyuncusuna ilişkin savunduğu temel tez nedir?', 'Üstün aktörün sahnede duygulara kapılmayıp soğukkanlı bir gözlem ve bilinçli teknikle rolünü her temsilde aynı kusursuzlukla denetlemesi gerektiği', ['Oyuncunun sahneye çıkmadan önce canlandıracağı karakterin tüm acılarını kendi özel yaşamında birebir deneyimleyip kendinden geçmesi gerektiği', 'Profesyonel aktörlerin yapay kaldığı, bu nedenle sahnede yalnızca eğitimsiz halktan amatör kişilerin oynatılması gerektiği', 'Oyuncunun yüz ifadelerini gizlemek için Antik Yunan\'daki gibi yeniden ahşap maske kullanımına dönülmesi gerektiği'], 'Diderot\'nun \'paradoks\'u, seyirciyi en çok duygulandıran büyük oyuncunun aslında sahnede hiç duygusallaşmayan, tepkilerini akıl ve teknikle yöneten kişi olduğudur.'),
  ('Fransız Romantizminin \'koltukta okunmak için tiyatro\' (Un Spectacle dans un fauteuil) anlayışıyla ince psikolojik ve şiirsel oyunlar yazan; Lorenzaccio ile Aşk Şakaya Gelmez (On ne badine pas avec l\'amour) yapıtlarının sahibi şair kimdir?', 'Alfred de Musset', ['Alfred de Vigny', 'Prosper Mérimée', 'Eugène Scribe'], 'İlk oyunu sahnede başarısız olunca sahne kısıtlamalarından bağımsız okuma tiyatrosu olarak başyapıtlar yazan Musset\'nin özellikle Floransa tiranını anlatan Lorenzaccio dramı 20. yüzyılda büyük sahne zaferi kazanmıştır.'),
  ('19. yüzyıl Fransa\'sında serim, düğüm, mektup veya mendil gibi mekanik ipuçları, beklenmedik sürprizler ve mantıksal çözümle saat gibi işleyen ticari kurgu tekniğini (\'iyi kurulu oyun\' / pièce bien faite) geliştiren üretken oyun yazarı kimdir?', 'Eugène Scribe', ['Émile Zola', 'Henry Becque', 'Paul Claudel'], 'Eugène Scribe ve ardılı Victorien Sardou\'nun geliştirdiği \'iyi kurulu oyun\' (well-made play) tekniği, önce İbsen\'in gerçekçi toplumcu oyunlarına iskelet sağlamış, ardından Bernard Shaw ve avangart tiyatrocularca eleştirilmiştir.'),
  ('Rönesans İtalya\'sının Vicenza kentinde 1580-1585 yılları arasında mimar Andrea Palladio tarafından Vitruvius\'un antik mimari ilkelerine göre tasarlanan ve sabit derinlik perspektifli sokak dekorlarıyla günümüze ulaşan en eski kapalı Rönesans tiyatrosu hangisidir?', 'Teatro Olimpico', ['Teatro alla Scala', 'Teatro San Carlo', 'Teatro La Fenice'], 'Palladio\'nun tasarlayıp Vincenzo Scamozzi\'nin sahne gerisindeki üç boyutlu yanılsamalı Tebai sokaklarıyla tamamladığı Teatro Olimpico, 1585\'te Kral Oidipus temsiliyle açılmıştır.'),
  ('Goethe\'nin 1773\'te yayımlanan ve üç birlik kuralını paramparça ederek elliden fazla mekân değişimiyle Shakespeare coşkusunu Almanya\'ya taşıyan, sağ eli demir protezli 16. yüzyıl imparatorluk şövalyesini konu alan ilk büyük oyunu hangisidir?', 'Götz von Berlichingen', ['Torquato Tasso', 'İphigenia Tauris\'te', 'Clavigo'], 'Genç Goethe\'nin Köylüler Savaşı dönemindeki özgür şövalyeyi anlattığı Götz von Berlichingen, Sturm und Drang hareketini ateşleyen tarihsel dramdır.'),
  ('Pierre Corneille\'in Roma ile Alba kentleri arasındaki savaşı bitirmek için iki kenti temsilen seçilen üçer kardeşin (Horatii ve Curiatii aileleri) birbirlerinin kayınbiraderi ve nişanlısı olmalarına rağmen vatan ödevi uğruna vuruşmasını işleyen trajedisi hangisidir?', 'Horace', ['Cinna', 'Nicomède', 'Sertorius'], '1640 tarihli Horace trajedisinde Corneille, aile bağları ve aşk duygusu karşısında tavizsiz devlet ve vatan ödevini (raison d\'État) en sert biçimiyle tartıştırır.'),
  ('İngiliz Restorasyon sonrası 18. yüzyıl töre komedyasında Richard Brinsley Sheridan\'ın Dedikodu Okulu (The School for Scandal) oyunundan türeyip dile yerleşen, her sözün altını üstüne getirerek cümle içinde kelimeleri gülünç biçimde yanlış kullanan karakter (The Rivals oyunundaki Bayan) kimdir?', 'Bayan Malaprop', ['Lady Windermere', 'Bayan Warren', 'Lady Macbeth'], 'Sheridan\'ın 1775 tarihli Rakipler (The Rivals) komedyasındaki Mrs. Malaprop karakteri, bilgili görünmek isterken sesçe benzer bambaşka kelimeleri karıştırma sanatına (\'malapropism\') adını vermiştir.'),
  ('Shakespeare\'in Othello dışındaki en ünlü \'Venedik\' oyunu Venedik Taciri ile Ben Jonson\'ın Volpone oyunu Rönesans İngilizlerinin İtalya algısı açısından birlikte değerlendirildiğinde Venedik kenti her iki eserde hangi toplumsal olguyu temsil eder?', 'Ticari kapitalizmin, sözleşme hukukunun, altın ve para dolaşımının insan ilişkilerini belirlediği kozmopolit merkezi', ['Feodal şövalyelik yeminlerinin ve tarımsal serflik düzeninin hiç bozulmadan korunduğu pastoral sığınağı', 'Papalık engizisyonunun tüm yabancı tüccarları ve tiyatroları yasakladığı kapalı manastır kentini', 'Antik Yunan demokrasisinin para kullanımını kaldırarak takas ekonomisiyle yönettiği ada devletini'], 'Erken modern İngiliz tiyatrosunda Venedik Cumhuriyeti; deniz ticareti, kredi, faiz, noter sözleşmeleri ve servet tutkusunun insan karakterini sınadığı erken kapitalist laboratuvar olarak kurgulanmıştır.'),
  ('Fransız Romantik tiyatrosunda Alexandre Dumas (baba) tarafından 1829\'da sahnelenen ve Victor Hugo\'nun Hernani\'sinden bir yıl önce Comédie-Française\'de başarı kazanan ilk tarihsel romantik düzyazı dram hangisidir?', 'III. Henri ve Sarayı', ['Kamelyalı Kadın', 'Monte Kristo Kontu', 'Antony'], 'Baba Alexandre Dumas\'nın III. Henri ve Sarayı (Henri III et sa cour) oyunu, sahnede ilk kez tarihsel romantik dramın zaferini müjdelemiş; Kamelyalı Kadın\'ı ise oğlu Genç Alexandre Dumas yazmıştır.'),
  ('Christopher Marlowe\'un Büyük Timur (Tamburlaine the Great) adlı iki bölümlük Rönesans trajedisinde İskitli bir çobanken ordularıyla Asya\'yı dize getiren Timur, esir aldığı hangi Osmanlı padişahını demir kafeste gezdirirken betimlenir?', 'Yıldırım Bayezid (Bajazeth)', ['Kanuni Sultan Süleyman (Solyman)', 'Genç Osman (Osman II)', 'Yavuz Sultan Selim (Selimus)'], 'Marlowe\'un 1587 dolaylarında sahnelenen Tamburlaine the Great oyununda Ankara Savaşı sonrası esir düşen Yıldırım Bayezid (\'Bajazeth\') ve eşi Zabina\'nın trajik sonu Batı kaynaklarındaki kafes efsanesine göre dramatize edilir.'),
  ('Alman Klasisizminin Weimar Tiyatrosu döneminde Goethe\'nin Euripides\'ten uyarlayarak yeniden yazdığı İphigenia Tauris\'te oyununda, barbar Kral Thoas\'ı ikna edip kanlı kurban geleneğini sona erdiren güç Euripides\'teki tanrısal hileden farklı olarak nedir?', 'İphigenia\'nın yalan söylemeyi reddederek krala tüm gerçeği açıklayan saf insancıllığı ve dürüstlüğü', ['Orestes\'in gizlice getirdiği Yunan donanmasının Tauris tapınağını denizden kuşatması', 'Tanrıça Athena\'nın bulutlar arasından inerek Kral Thoas\'ı yıldırım ateşiyle korkutması', 'Pylades\'in tapınak muhafızlarına uyku iksirli şarap içirip kutsal heykeli çalması'], 'Goethe\'nin Weimar Klasisizmi (Humanität) anlayışını yansıtan İphigenia\'sında düğümü hile ya da deus ex machina değil, kadının lekesiz ahlaki doğruluğu ve Kral Thoas\'ın soylu hoşgörüsü çözer.'),
  ('Orta Çağ\'dan Rönesans\'a geçişte İspanyol edebiyatında Fernando de Rojas\'ın 1499\'da yirmi bir perde (diyaloglu roman/oyun) olarak yayımladığı, Calisto ile Melibea\'nın trajik aşkına aracılık eden yaşlı ve kurnaz çöpçatan-büyücü kadının adıyla anılan başyapıt hangisidir?', 'La Celestina', ['Fuenteovejuna', 'Numancia Kuşatması', 'El Cid Destanı'], 'Asıl adı Calisto ve Melibea\'nın Trajikomedisi olan yapıt, açgözlü ve keskin zekâlı yaşlı çöpçatan La Celestina karakterinin gücü nedeniyle onun adıyla ölümsüzleşmiştir.'),
  ('Shakespeare\'in Atinalı Timon (Timon of Athens) trajedisinde servetini sözde dostlarına cömertçe dağıttıktan sonra iflas edince kimsenin kendisine borç vermemesi üzerine insanlıktan tiksinip ormandaki mağaraya çekilen Timon, ağaç kökü kazarken ne bulur?', 'Gömülü bir küp dolusu altın bulur ve bunu insanlığın birbirini mahvetmesi için fahişelerle isyancılara dağıtır', ['Büyük İskender\'in kayıp vasiyetnamesini bulup Atina senatosunu tek başına satın alır', 'Şifalı bir pınar keşfederek kente geri dönüp veba salgınını iyileştiren bilge hekim olur', 'Eski dostlarının mağaraya sakladığı suikast silahlarını bulup Atina komutanı Alkibiades\'e sığınır'], 'Karl Marx\'ın da paranın yabancılaştırıcı doğasını açıklarken alıntıladığı ünlü sahnede Timon, insanlardan kaçarken toprakta yeniden altın bulur ve altının \'akı kara, çirkini güzel yapan\' gücünü lanetler.'),
  ('Goethe\'nin Faust yapıtının İkinci Bölümü\'nde Faust ile Antik Yunan güzelliğinin simgesi Spartalı Helena\'nın zamansız evliliğinden doğan, Klasik güzellikle Romantik coşkunun birleşimini temsil eden ve İkarus gibi göğe sıçrayıp düşerek sönen delikanlı kimdir?', 'Euphorion', ['Philemon', 'Lynkeus', 'Famulus'], 'Goethe, Faust II\'de Faust (Kuzey/Romantizm) ile Helena\'nın (Antik Yunan/Klasisizm) oğlu Euphorion şahsında hem bu iki estetiğin sentezini hem de Yunanistan\'da ölen İngiliz şair Lord Byron\'ı simgeleştirmiştir.'),
  ('Vittorio Alfieri\'nin 18. yüzyıl sonunda İtalyan ulusal bilincini (Risorgimento) uyandırmak amacıyla yazdığı ve İncil\'deki ilk İsrail kralının genç çoban Davut\'a duyduğu iktidar kıskançlığı ile ruhsal çöküşünü işleyen trajedisi hangisidir?', 'Saul', ['Mirandolina', 'Adelchi', 'Carmagnola Kontu'], 'Tiranlığa karşı özgürlük tutkusuyla yalın ve sert klasik trajediler yazan Vittorio Alfieri\'nin 1782 tarihli Saul adlı eseri, İtalyan trajedi edebiyatının zirvesi kabul edilir.'),
  ('Shakespeare\'in soneleri dışında kırka yakın oyununu yazarın ölümünden yedi yıl sonra (1623) derleyerek kaybolmaktan kurtaran ve tiyatro tarihinde \'Birinci Folyo\' (First Folio) adıyla bilinen külliyatı yayımlayan iki oyuncu arkadaşı kimlerdir?', 'John Heminges ve Henry Condell', ['Richard Burbage ve Will Kempe', 'Francis Beaumont ve John Fletcher', 'Thomas Middleton ve John Ford'], 'Macbeth, Julius Caesar, On İkinci Gece ve Fırtına dahil on sekiz Shakespeare oyunu daha önce hiç basılmamışken, kumpanya arkadaşları Heminges ve Condell\'in 1623\'te bastırdığı First Folio sayesinde günümüze ulaşmıştır.'),
  ('İspanyol Altın Çağı\'nda Lope de Vega\'nın 1609\'da kaleme aldığı Çağımızda Komedya Yazmanın Yeni Sanatı adlı manzum bildiride klasik kurallara karşı savunduğu yenilikçi ilke nedir?', 'Trajedi ile komediyi doğadaki gibi harmanlayıp üç perde (jornadas) düzeninde halkın zevkini ve canlı eylemi esas almak', ['Oyunları yalnızca Latince yazarak üniversite dışındaki halk seyircisini tiyatrodan uzaklaştırmak', 'Beş perdelik Yunan koro yapısına geri dönüp sahnede hiçbir aşk konusuna yer vermemek', 'Dekor değişimini tümüyle yasaklayarak tüm olayı üç saatlik gerçek zamana sıkıştırmak'], 'Lope de Vega, \'Aristo ve Plautus\'u yazarken odaya kilitliyorum\' diyerek İspanyol ulusal tiyatrosunu üç perdeli, dinamik ve trajikomik \'comedia nueva\' formuna kavuşturmuştur.'),
  ('William Shakespeare\'in Fırtına oyunundaki Caliban ile Ariel figürleri sömürgecilik sonrası (postkolonyal) ve simgesel edebiyat eleştirisinde sıklıkla hangi karşıtlığı temsil edecek biçimde yorumlanır?', 'Ariel uçucu zekâ, sanat ve hava unsurunu; adanın yerlisi Caliban ise toprak, bedensel içgüdü ve sömürgeleştirilen ötekini', ['Ariel Katolik kilisesinin engizisyon gücünü; Caliban ise Venedik tüccar sınıfının deniz bankacılığını', 'Ariel ölüm ve intikam meleğini; Caliban ise kusursuz saray nezaketini ve şövalye sadakatini', 'Ariel kıskançlık yüzünden eşini boğan komutanı; Caliban ise ülkesini kızlarına paylaştıran yaşlı kralı'], 'Prospero adaya gelmeden önce adanın sahibi olan ve \'Bana dilinizi öğrettiniz, kazancım küfretmeyi bilmek oldu\' diyen Caliban ile hava ruhu Ariel, doğa-kültür ve efendi-sömürge tartışmalarının merkezindedir.'),
  ('Victor Hugo\'nun Hernani oyununda Kral Don Carlos\'un takip ettiği dağ haydudu Hernani (Don Juan d\'Aragon), düğün gecesi yaşlı Don Ruy Gomez de Silva\'nın üflediği av borusunu duyunca neden zehir içerek canına kıyar?', 'Yaşlı soylu kendisini krala teslim etmeyip misafirlik hakkıyla koruduğunda boruyu çaldığı an canını vereceğine dair şeref yemini ettiği için', ['Evlendiği Doña Sol\'ün aslında çocukken ayrıldığı öz kız kardeşi olduğunu boru işaretiyle öğrendiği için', 'Kralın muhafızları şatoyu kuşattığında canlı yakalanıp engizisyonda yakılmaktan korktuğu için', 'Sevgilisinin düğün şarabına yanlışlıkla uyku ilacı yerine ölümcül zehir karıştırdığını sandığı için'], 'Kastilya misafirperverliği gereği krala sığınmacısını vermeyen yaşlı Silva\'ya kendi av borusunu bırakan Hernani, en mutlu anında boru çalınınca şövalye sözünden dönmeyip Doña Sol ile birlikte zehir içer.'),
  ('İngiliz Restorasyon komedyasının zirvesi sayılan Dünyanın Düzeni (The Way of the World, 1700) adlı oyunda Mirabell ile bağımsız ruhlu Millamant\'ın evlenmeden önce karşılıklı özgürlük koşullarını sıraladıkları ünlü pazarlık sahnesini yazan sanatçı kimdir?', 'William Congreve', ['George Etherege', 'William Wycherley', 'Aphra Behn'], 'William Congreve\'in Dünyanın Düzeni eseri, nükteli diyalogları ve Millamant\'ın evlilikte bireysel özerkliğini şart koştuğu \'proviso\' sahnesiyle töre komedyasının şaheseridir.'),
  ('İngiltere\'de profesyonel oyun yazarlığı yaparak geçimini kalemiyle kazanan ilk kadın yazar kabul edilen ve Restorasyon döneminde Gezgin (The Rover, 1677) komedyasını kaleme alan edebiyatçı kimdir?', 'Aphra Behn', ['Hrotsvitha', 'Mary Shelley', 'Jane Austen'], 'Virginia Woolf\'un \'Bütün kadınlar Aphra Behn\'in mezarına çiçek bırakmalıdır, çünkü kalemleriyle para kazanma hakkını onlara o kazandırdı\' dediği yazar, Restorasyon tiyatrosunun önde gelen ismidir.'),
  ('10. yüzyılda Almanya\'daki Gandersheim Manastırı\'nda yaşayarak Terentius\'un Roma komedyalarını Hristiyan bakirelerin direniş öykülerine dönüştüren ve Antik Çağ sonrasında Batı\'da bilinen ilk oyun yazarı (ve tarihteki ilk kadın oyun yazarı) sayılan rahibe kimdir?', 'Gandersheimlı Hrotsvitha', ['Bingeli Hildegard', 'Avilalı Teresa', 'Pizanlı Christine'], 'Saksonyalı rahibe Hrotsvitha, Latince yazdığı altı oyunla (Dulcitius, Abraham vb.) Terentius\'un pagan üslubuna alternatif Hristiyan dramları üretmiş ve Orta Çağ\'ın en erken oyun yazarı olmuştur.'),
  ('Molière\'in Bilgiç Kadınlar (Les Femmes savantes) adlı manzum komedyasında evdeki kadınların sahte bilim, dilbilgisi ve ukala şair Trissotin hayranlığı yüzünden hizmetçiyi bile \'gramer kuralını çiğnedi\' diye kovmasına karşı sağduyuyu ama pısırıklığı temsil eden aile reisi kimdir?', 'Chrysale', ['Orgon', 'Harpagon', 'Alceste'], '\'İyi bir çorba güzel sözden iyidir\' diyen ev babası Chrysale, karısı Philaminte\'in ve ukala şair Trissotin\'in entelektüel züppeliği karşısında bocalayan burjuva tipidir.'),
  ('Fransız Klasisizminde Pierre Corneille\'in 1643 tarihli Polyeucte adlı eseri konu seçimi bakımından çağdaşı diğer klasik trajedilerden hangi yönüyle ayrılır?', 'Yunan-Roma pagan mitolojisi yerine Roma egemenliğindeki Ermenistan\'da Hristiyanlığı seçip putları kıran bir din şehidini işlemesiyle', ['Bütünüyle düzyazıyla yazılıp sahnede gerçek koro ve bale topluluğuna yer vermesiyle', 'Olay örgüsünü yirmi yıllık bir zaman dilimine ve üç ayrı kıtaya yaymasıyla', 'Sonunda tüm kötülerin cezalandırılıp kahramanın tahta çıktığı neşeli bir düğünle bitmesiyle'], 'Boileau Hristiyanlık gizemlerinin trajedi sahnesine taşınmasına mesafeli dursa da Corneille\'in Polyeucte\'ü (ve daha sonra Racine\'in Athalie\'si) dinsel trajedinin en güçlü istisnalarını oluşturmuştur.'),
  ('Carlo Goldoni\'nin Kahvehane (La bottega del caffè) adlı komedyasında Venedik\'in küçük bir meydanındaki kahvehanenin müdavimi olup dürbünüyle herkesin özel yaşamını gözetleyen ve çıkarardığı iftiralarla yuvaları yıkmaya çalışan kötücül dedikoducu kimdir?', 'Don Marzio', ['Truffaldino', 'Şövalye Ripafratta', 'Pantalone'], 'Dürüst kahveci Ridolfo\'nun karşısında dedikodu ve iftira makinesi Napolili soylu Don Marzio\'yu çizen Goldoni, Venedik meydan yaşamını koro bütünlüğünde resmeder.'),
  ('Shakespeare\'in Kış Masalı (The Winter\'s Tale) adlı geç dönem romans oyununda Sicilya Kralı Leontes\'in temelsiz kıskançlığı yüzünden öldü sanılan Kraliçe Hermione, on altı yıl sonra saraya nasıl geri döner?', 'Paulina\'nın evindeki şapelde sergilenen mermer heykelinin müzik eşliğinde canlanıp kürsüden inmesiyle', ['Erkek bir gezgin ozan kılığında saray şölenine katılıp arp çalarak kimliğini açıklamasıyla', 'Bohemya kıyılarında çobanların büyüttüğü kızı Perdita\'nın düğün gemisinde kaptan olarak belirmesiyle', 'Delphoi Apollon Tapınağı\'ndan gelen başrahibenin peçesini açmasıyla'], 'Kış Masalı\'nın son perdesinde sadık nedime Paulina\'nın on altı yıl gizlediği Hermione\'nin \'canlanan heykel\' sahnesi, Shakespeare tiyatrosunun en büyüleyici bağışlama ve yeniden doğuş mucizesidir.'),
  ('19. yüzyıl Alman tiyatrosunda Romantizmden Gerçekçiliğe geçiş köprüsünü kuran ve marangoz Usta Anton\'un \'Ben bu dünyayı artık anlamıyorum!\' repliğiyle dar görüşlü küçük burjuva ahlakının kızını intihara sürükleyişini Maria Magdalena (1844) dramında işleyen yazar kimdir?', 'Friedrich Hebbel', ['Gerhart Hauptmann', 'Frank Wedekind', 'Franz Grillparzer'], 'Friedrich Hebbel, Maria Magdalena ile burjuva trajedisini soylu-halk çatışmasından çıkarıp bizzat küçük burjuva sınıfının kendi içindeki boğucu namus kalıplarının trajedisine dönüştürmüştür.'),
  ('İtalyan Rönesans şairi Torquato Tasso\'nun 1573\'te Ferrara sarayı için yazdığı, çoban genci ile su perisi Silvia\'nın aşkını işleyerek Avrupa\'da pastoral dram türünün en parlak örneğini oluşturan eseri hangisidir?', 'Aminta', ['Kurtarılmış Kudüs', 'Sadık Çoban', 'Orfeo'], 'Tasso\'nun Aminta adlı lirik-pastoral oyunu (Guarini\'nin Sadık Çoban\'ı ile birlikte) hem Rönesans saray tiyatrosunu hem de erken dönem İtalyan operasının doğuşunu derinden etkilemiştir.'),
  ('William Shakespeare\'in trajedilerinden Macbeth\'te Lady Macbeth\'in ellerini ovuşturarak yürüdüğü uyurgezerlik sahnesi dilbilimsel açıdan neden özel bir dramatik anlam taşır?', 'Oyun boyunca soylu karakterler gibi ölçülü manzum dille (blank verse) konuşan Lady Macbeth\'in akıl sağlığı çözülünce kopuk düzyazıya düşmesiyle', ['İskoç lehçesini bırakıp bir anda yalnızca Latince kilise duaları ve Fransızca saray deyimleri mırıldanmasıyla', 'O güne dek sahnede hiç konuşmayan dilsiz bir karakterken ilk kez uyurgezerlik anında kafiyeli sone okumasıyla', 'Hizmetçisi ve saray hekimiyle birer dizelik stikhomythia kalıbında felsefi tartışmaya girmesiyle'], 'Shakespeare soyluları çoğunlukla uyaksız ölçülü şiirle (blank verse), alt sınıfları veya delilik anlarını ise düzyazıyla konuşturur; demir iradeli Lady Macbeth\'in uyurgezerlik sahnesinde düzyazıya geçmesi zihinsel parçalanışının biçimsel kanıtıdır.'),
  ('18. yüzyıl sonu ile 19. yüzyıl başında Avusturya tiyatrosunun en büyük klasik-romantik şairi kabul edilen, Medea efsanesini Altın Post üçlemesiyle ve Deniz ve Aşk Dalgaları (Hero ile Leandros) trajedisiyle yeniden yorumlayan Viyanalı yazar kimdir?', 'Franz Grillparzer', ['Johann Nestroy', 'Ferdinand Raimund', 'Arthur Schnitzler'], 'Avusturya ulusal tiyatrosunun (Burgtheater) başyazarı sayılan Franz Grillparzer, Weimar Klasisizminin biçim kusursuzluğunu Viyana Barok geleneği ve derin psikolojik çözümlemeyle birleştirmiştir.'),
  ('Henrik Ibsen\'in "Yaban Ördeği" oyununda Gregers Werle\'nin savunduğu "mutlak hakikat" ilkesine karşı Doktor Relling\'in ileri sürdüğü "yaşam yalanı" kavramı neyi ifade eder?', 'Sıradan insanların katlanılmaz gerçeklerle yüzleşmek yerine tutundukları avuntularla ayakta kalabildiğini', ['Tiyatro oyuncularının sahnede seyirciyi ikna etmek için başvurdukları abartılı taklit yöntemlerini', 'Politikacıların seçim dönemlerinde halkı yönlendirmek amacıyla ürettikleri ideolojik söylemleri', 'Doğa bilimcilerinin evrim kuramını açıklarken kullandıkları geçici varsayımları'], 'Doktor Relling, Ekdal ailesinin yıkımını öngörerek ortalama insanın yaşayabilmek için bir "yaşam yalanına" muhtaç olduğunu savunur.'),
  ('Ibsen\'in "problem oyunu" (dava oyunu) anlayışının 19. yüzyıl sonu Avrupa tiyatrosuna getirdiği en köklü yapısal dönüşüm hangisidir?', 'Entrika ağırlıklı "iyi kurgulanmış oyun" kalıplarını tartışma sahnesine dönüştürerek toplumsal kurumları sorgulaması', ['Antik Yunan korosunu modern şehir meydanlarına taşıyarak manzum tiratları yeniden canlandırması', 'Sahne dekorunu tamamen kaldırarak oyuncunun yalnızca pandomim sanatıyla iletişim kurmasını sağlaması', 'Seyircinin sahneye çıkıp oyunun sonunu oylamasına dayanan doğaçlama bir kurgu geliştirmesi'], 'Ibsen, Scribe tarzı yapay entrika oyunlarının tekniğini alıp son perdeye uzlaşma yerine keskin bir toplumsal-ahlaki tartışma yerleştirmiştir.'),
  ('Henrik Ibsen\'in son oyunu olan ve heykeltraş Arnold Rubek ile eski modeli İrena\'nın sanatı yaşamın önüne koymalarının pişmanlığını işleyen eser hangisidir?', 'Biz Ölüler Uyanınca', ['Küçük Eyolf', 'İmparator ve Galileli', 'Toplumun Direkleri'], '1899 tarihli "Biz Ölüler Uyanınca", Ibsen\'in sanat ve yaşam arasındaki çatışmayı sorguladığı dramatik sonsözüdür.'),
  ('Çehov\'un "Martı" adlı oyununda genç yazar Treplev\'in göl kıyısında sahnelediği sembolist oyun girişimi ile annesi Arkadina\'nın tepkisi hangi sanatsal çatışmayı temsil eder?', 'Yeni biçimler arayan avangart sanat anlayışı ile yerleşik, geleneksel ve ticari tiyatro alışkanlıkları arasındaki çatışmayı', ['Köylü halk tiyatrosu geleneği ile Çarlık sarayının sansürcü bürokrasisi arasındaki siyasal mücadeleyi', 'Dini içerikli ortaçağ mister oyunları ile aydınlanma çağı rasyonalist komedyaları arasındaki karşıtlığı', 'Doğalcı belgesel tiyatro ile epik-diyalektik tiyatro kuramı arasındaki kuramsal ayrılığı'], 'Treplev\'in "yeni biçimler gerek" diyerek sunduğu soyut oyun, geleneksel tiyatronun yıldızı olan annesi Arkadina tarafından alaya alınır.'),
  ('Çehov\'un "Vişne Bahçesi"ni "dram" olarak sahneleyen Stanislavski\'ye itiraz ederek eserin aslında "komedya, hatta yer yer fars" olduğunu savunmasının temel nedeni nedir?', 'Karakterlerin yaklaşan yıkım karşısındaki çocuksu aymazlıklarını ve gerçeklikten kopukluklarını ironik bir mesafeyle işlemesi', ['Oyunun sonunda Ranevskaya ailesinin piyangodan para kazanarak bahçeyi geri alması ve mutlu bir düğün yapılması', 'Eserdeki tüm uşak karakterlerin İtalyan halk komedyasındaki maskeli soytarılar gibi akrobasi yapması', 'Toplumsal değişimin hiçbir hüzün barındırmayan neşeli bir taşra eğlencesi olarak resmedilmesi'], 'Çehov, duygusal ağlaklıktan kaçınmış; karakterlerinin trajikomik çaresizliğinin ve yanılsamalarının gülünç yanını da göstermek istemiştir.'),
  ('Çehov\'un henüz kariyerinin başında yazdığı, daha sonra "Vanya Dayı"ya dönüştürdüğü ve doğayı koruma bilincine sahip bir doktoru merkezine alan erken dönem oyunu hangisidir?', 'Orman Cini', ['İvanov', 'Teklif', 'Ayı'], '1889 tarihli "Orman Cini" (Leşiy), Çehov tarafından yeniden yazılarak başyapıtı "Vanya Dayı"ya dönüştürülmüştür.'),
  ('Bernard Shaw\'un "Silahlar ve İnsan" (Arms and the Man) adlı oyununda "çikolata askeri" olarak anılan İsviçreli paralı asker Bluntschli hangi anlayışı yıkmak için kurgulanmıştır?', 'Savaşı ve askerliği yücelten romantik kahramanlık yanılsamasını gerçekçi ve faydacı bir bakışla bozmak için', ['Avrupa ordularındaki lojistik ve beslenme eksikliklerini askeri yönetimlere rapor etmek için', 'Balkan uluslarının bağımsızlık savaşlarında yabancı lejyonerlerin ihanetini belgelemek için', 'Şövalyelik ruhunun modern ateşli silahlar karşısında bile üstün geldiğini kanıtlamak için'], 'Mermi yerine cebinde çikolata taşıyan Bluntschli, Bulgar subay Sergius\'un yapay romantik kahramanlık pozlarının karşısına sağduyuyu koyar.'),
  ('Bernard Shaw\'un Çehov tarzında bir "Avrupa taşrası fantezisi" olarak alt başlıklandırdığı ve Birinci Dünya Savaşı arifesinde İngiliz aydınlarının vurdumduymazlığını simgeleyen oyunu hangisidir?', 'Kırgınlar Evi', ['İnsan ve Üstün İnsan', 'Doktorun İkilemi', 'Androkles ve Aslan'], '"Kırgınlar Evi" (Heartbreak House), Kaptan Shotover\'ın gemi biçimindeki evinde felakete sürüklenen Avrupa uygarlığını alegorik olarak eleştirir.'),
  ('Bernard Shaw\'un basılı oyun metinlerinin başına oyun kadar uzun "önsözler" ve ayrıntılı sahne direktifleri eklemesinin temel amacı nedir?', 'Oyunun ardındaki toplumsal, ekonomik ve felsefi tezleri okuyucuya doğrudan ve kapsamlı bir makale titizliğiyle aktarmak', ['Yönetmenlerin metin üzerinde hiçbir yorum yapamaması için oyuncuların adım sayılarını milimetrik olarak sabitlemek', 'Sansür kurullarının dikkatini oyunun kendisinden uzaklaştırarak resmi denetçileri uzun metinlerle oyalamak', 'Tiyatro biletlerinin pahalı olması nedeniyle oyunların sahnelenmesinden tamamen vazgeçip romana yönelmek'], 'Shaw, oyunlarını yalnızca seyredilecek eğlenceler değil, okunup üzerinde tartışılacak düşünsel metinler olarak görmüştür.'),
  ('Pirandello\'nun "Size Öyle Geliyorsa Öyledir" adlı oyununda Bay Ponza ile kayınvalidesi Bayan Frola\'nın birbirini deli suçlaması ve peçeli kadının oyun sonunda "Ben kimin için neysem oyum" demesi neyi kanıtlar?', 'Mutlak ve tek bir nesnel hakikatin bulunmadığını, gerçeğin bireylerin algısına göre göreceli olduğunu', ['Kasaba polisinin kimlik kayıtlarını tutmakta yetersiz kaldığını ve resmi belgelerin önemini', 'Deprem felaketlerinin insanlarda kalıcı şizofreni ve hafıza kaybı yarattığını', 'İtalyan aile yapısında kayınvalideler ile damatlar arasındaki geleneksel otorite kavgasını'], 'Pirandello\'nun görecelik (rölativizm) felsefesine göre herkesin kendine ait bir gerçeği vardır ve dışarıdan kesin yargıya varılamaz.'),
  ('Pirandello\'nun kuramlaştırdığı "çıplak maskeler" (maschere nude) kavramı insan kişiliğine dair hangi görüşü dile getirir?', 'Bireyin toplum içinde sabit bir kimliğe zorlandığını, oysa bu toplumsal maskenin altında sürekli değişen ve parçalanmış bir benlik yattığını', ['Oyuncuların sahneye hiçbir makyaj ve kostüm kullanmadan tamamen doğal halleriyle çıkmaları gerektiğini', 'Antik Yunan trajedilerindeki abartılı yüz maskelerinin modern sahnede yeniden kullanılmasının zorunlu olduğunu', 'İnsanların doğuştan saf ve günahsız olup yalnızca büyük şehir hayatında kötülüğü öğrendiğini'], 'Pirandello külliyatına "Çıplak Maskeler" adını vererek insanın toplumca dayatılan rol/maske ile içsel akışı arasındaki trajikomik sıkışmışlığını vurgulamıştır.'),
  ('Lorca\'nın "Bernarda Alba\'nın Evi" oyununda en küçük kız Adela\'nın yas kurallarına meydan okuyarak yeşil elbise giymesi ve Bernarda\'nın bastonunu kırması neyin göstergesidir?', 'Yaşama sevincinin, cinsel özgürlük arzusunun ve gençliğin baskıcı otoriteye karşı trajik başkaldırısının', ['Ailenin miras paylaşımında küçük kıza haksızlık yapılmasına duyulan maddi öfkenin', 'Köydeki rahibin kilise korosuna katılması için Adela\'ya verdiği gizli desteğin', 'Bernarda\'nın yaşlılık nedeniyle ev yönetimini gönüllü olarak en küçük kızına devretmesinin'], 'Pepe el Romano\'ya aşık olan Adela, siyah yas örtülerinin ortasında yeşil elbisesiyle yaşam dürtüsünü temsil eder; ancak bu isyan intiharla son bulur.'),
  ('Lorca\'nın geleneksel gerçekçi kalıpları tamamen kırarak New York yıllarında yazdığı ve bilinçaltı, zaman ile kimlik karmaşasını işlediği gerçeküstücü (sürrealist) oyunu hangisidir?', 'Beş Yıl Geçince', ['Kunduracının Harika Karısı', 'Doña Rosita ya da Çiçeklerin Dili', 'Özgürlük Kahramanı Mariana Pineda'], '"Beş Yıl Geçince" (Aradan Beş Yıl Geçince) ve "İzleyici (El Público)", Lorca\'nın avangart ve sürrealist "imkansız tiyatrosunun" en çarpıcı örnekleridir.'),
  ('Strindberg\'in 1901\'de yazdığı "Bir Düş Oyunu" (Ett drömspel) adlı eseri hangi özelliğiyle 20. yüzyıl dışavurumcu ve avangart tiyatrosuna kapı açmıştır?', 'Zaman-mekan mantığını ve nedenselliği yıkarak sahneyi rüya gören tek bir bilincin akışkan kurallarına göre kurgulamasıyla', ['Sahneye gerçek ağaçlar, canlı hayvanlar ve çalışan buharlı makineler getirerek fotoğrafik gerçekliği kusursuzlaştırmasıyla', 'Yalnızca tarihsel mahkeme tutanaklarını kullanarak İsveç krallarının yargılanmasını belgesel biçimde sunmasıyla', 'Klasik Fransız trajedisindeki üç birlik kuralını İskandinav mitolojisine harfiyen uygulamasıyla'], 'Strindberg\'in rüya mantığına dayalı bu oyunu, zaman ve mekanın iç içe geçtiği, karakterlerin bölünüp birleştiği modern dışavurumcu sahnenin öncüsüdür.'),
  ('Maksim Gorki\'nin "Ayaktakımı Arasında" oyununda gezgin ihtiyar Luka\'nın ölmekte olan insanlara teselli verici yalanlar söylemesine karşılık Satin\'in "Yalan kölelerin ve efendilerin dinidir; gerçek ise özgür insanın tanrısıdır!" demesi neyi tartışmaya açar?', 'Merhamet kaynaklı avuntuların insanı uyuşturduğu ve gerçek kurtuluşun acı hakikatle yüzleşip onuru korumaktan geçtiği düşüncesini', ['Tiyatro sanatının halka yalnızca neşeli masallar anlatarak günlük dertleri unutturması gerektiği ilkesini', 'Çarlık Rusyası\'nda gezgin dervişlerin ve din adamlarının barınakları yönetmesi gerektiği savını', 'Yoksulluğun insan ruhunu arındıran kutsal ve değiştirilmemesi gereken bir yazgı olduğu inancını'], 'Gorki, Ibsen\'in "Yaban Ördeği"ndeki "yaşam yalanı" tartışmasını toplumsal bir boyuta taşıyarak pasif teselli yerine insan onurunu ve gerçeği savunur.'),
  ('Stanislavski yöntemine göre çalışan bir oyuncunun sahnedeki bir kayıp sahnesinde kendi geçmişinde yaşadığı benzer bir üzüntüyü hatırlayarak duygulanması hangi teknikle adlandırılır?', 'Coşku belleği (duyusal/duygusal bellek)', ['Yabancılaştırma efekti (V-Efekt)', 'Biyomekanik oyunculuk', 'Vahşet tiyatrosu sağaltımı'], 'Stanislavski\'nin erken dönem çalışmalarında öne çıkan "coşku belleği", oyuncunun kişisel deneyimlerinden yararlanarak sahnede sahici duygu üretmesini amaçlar.'),
  ('Maurice Maeterlinck\'in "durağan tiyatro" (statik tiyatro) kuramı ve "Körler" adlı oyunu modern tiyatrodaki hangi sonraki akımın habercisi sayılır?', 'Bekleyiş, belirsizlik ve varoluşsal çaresizlik atmosferiyle Samuel Beckett\'in absürt tiyatrosunun', ['Sınıf mücadelesini fabrika grevleri üzerinden anlatan sosyalist gerçekçi işçi tiyatrosunun', 'Tarihsel savaşları belgesel projeksiyonlarla sunan Erwin Piscator\'un politik tiyatrosunun', 'Geleneksel halk masallarını neşeli şarkılarla birleştiren Amerikan müzikal komedyasının'], 'Ormanda ölmüş kılavuz rahibin etrafında çaresizce bekleyen körleri anlatan Maeterlinck\'in "Körler"i, "Godot\'yu Beklerken"in doğrudan öncüllerinden biridir.'),
  ('1896 yılında Paris\'te sahnelendiğinde büyük skandal yaratan ve kaba, açgözlü, zorba bir tiplemeyle hem burjuvaziyi hem iktidarı hicvederek sürrealist ve absürt tiyatroya öncülük eden Alfred Jarry eseri hangisidir?', 'Kral Übü', ['Tiresias\'ın Memeleri', 'Orfe', 'Kan Fışkırtısı'], 'Alfred Jarry\'nin "Merdre!" (B.k!) ünlemiyle açılan "Kral Übü" (Ubu Roi) adlı eseri, avangart tiyatronun başlangıç noktası kabul edilir.'),
  ('Antonin Artaud\'nun "Tiyatro ve İkizi" adlı kitabında ortaya koyduğu "Vahşet Tiyatrosu" (Théâtre de la Cruauté) kuramı aşağıdakilerden hangisini hedefler?', 'Batı tiyatrosunu yazılı metnin egemenliğinden kurtarıp ses, ışık, ritüel ve beden diliyle seyircinin bilinçaltını sarsmayı', ['Sahnede gladyatör dövüşlerine benzer gerçek fiziksel yaralamalar ve kanlı işkence gösterileri düzenlemeyi', 'Klasik Fransız edebiyatının unutulmuş manzum metinlerini diksiyon kurallarına bağlı kalarak yeniden okumayı', 'Seyirciyi rahat koltuklarda eğlendirerek burjuva toplumunun ahlaki değerlerini pekiştirmeyi'], 'Artaud\'daki "vahşet" fiziksel sadizm değil, yaşamın acımasız kozmik zorunluluğuyla seyirciyi büyüsel bir ritüel içinde yüzleştirmektir.'),
  ('Rus yönetmen Vsevolod Meyerhold\'un Stanislavski\'nin psikolojik doğalcılığına tepki olarak geliştirdiği, oyuncunun bedenini disiplinli ve ritmik hareketlerle kullanan oyunculuk yöntemi hangisidir?', 'Biyomekanik oyunculuk', ['Metot oyunculuğu', 'Doğalcı özdeşleşme', 'Sözsüz oda tiyatrosu'], 'Meyerhold, sirk, pandomim ve Taylorizm ilkelerinden esinlenerek içten dışa değil, fiziksel hareketten duyguya giden "biyomekanik" sistemini kurmuştur.'),
  ('John Millington Synge\'in tek perdelik trajedisi "Denize Giden Atlılar"da yaşlı anne Maurya\'nın son oğlu Bartley\'yi de azgın denize kurban verdikten sonra ulaştığı ruh hali neyi ifade eder?', 'Artık denizin kendisinden alabileceği hiçbir şey kalmadığı için ulaştığı trajik kabullenişi ve vakur dinginiği', ['Deniz ticaretini yöneten İngiliz gemi sahiplerine karşı silahlı bir köylü ayaklanması başlatma kararını', 'Oğullarının intikamını almak için balıkçı teknelerini ateşe veren çılgınca bir öfke patlamasını', 'Kasabayı terk ederek Amerika\'ya göç etme ve yeni bir hayat kurma umudunu'], 'Aran Adaları\'ndaki balıkçıların doğayla amansız mücadelesini anlatan bu kısa başyapıt, Antik Yunan trajedisi yoğunluğunda bir kabullenişle biter.'),
  ('Alman Dışavurumcu (Ekspresyonist) tiyatrosunda (Georg Kaiser, Ernst Toller vb.) karakterlerin özel isimler yerine "Kasiyer", "Milyarder", "Anne", "Adsız İnsan" gibi sıfatlarla anılmasının kuramsal nedeni nedir?', 'Bireysel psikolojik ayrıntıları ayıklayarak çağdaş sanayi toplumunda ezilen insanın evrensel özünü ve ruhsal çığlığını yansıtmak', ['Polis sansüründen korunmak amacıyla gerçek siyasetçilerin kimliklerini gizli tutmak', 'Oyuncuların kalabalık kadrolu oyunlarda birbirlerinin isimlerini ezberlemekte zorlanmasını önlemek', 'Geleneksel İtalyan halk komedyasındaki neşeli uşak ve efendi tiplerini yeniden canlandırmak'], 'Dışavurumcu tiyatro doğalcı bireyselleştirmeyi reddeder; "İstasyon Dramı" yapısında soyutlanmış tipler üzerinden "Yeni İnsan" arayışını sergiler.'),
  ('Karel Čapek\'in "R.U.R." adlı oyununda yapay işçi olarak üretilen robotların sonunda insanlığı ortadan kaldırması hangi temel eleştiriyi içerir?', 'Teknolojik gelişmenin kâr hırsıyla birleştiğinde insan emeğini değersizleştirip insanlığı kendi yarattığı araçların kurbanı haline getirmesini', ['Doğu Avrupa ülkelerinin tarımsal üretimden sanayiye geçmekte Batı\'ya kıyasla çok geç kalmasını', 'Bilim insanlarının laboratuvar deneylerinde hayvan haklarını yeterince gözetmemesini', 'Orta Çağ simyacılarının ölümsüzlük iksiri arayışlarının modern tıpta devam etmesini'], 'Čapek, makineleşme çağında ruhsuz verimlilik saplantısının uygarlığı yok oluşa sürükleyebileceği uyarısında bulunmuştur.'),
  ('Eugene O\'Neill\'in Aiskhylos\'un "Oresteia" üçlemesini Amerikan İç Savaşı sonrasındaki New England\'lı bir aileye uyarladığı "Elektra\'ya Yas Yaraşır" adlı eseri hangi kuramsal birleşimi gerçekleştirir?', 'Antik Yunan trajedisindeki kader ve kan davası motifini Freudyen psikanaliz ve aile içi bastırılmış arzularla yeniden yorumlar', ['Geleneksel kovboy filmlerindeki düello sahnelerini epik tiyatronun yabancılaştırma şarkılarıyla birleştirir', 'Amerikan yerlilerinin şaman ritüellerini Viktorya dönemi salon komedyası kalıpları içine yerleştirir', 'Büyük Buhran dönemindeki borsa çöküşünü belgesel gazetecilik tekniğiyle mahkeme sahnesine taşır'], 'O\'Neill, Mannon ailesi üzerinden Agamemnon-Klytaimnestra-Elektra-Orestes mitini modern psikolojik komplekslere dönüştürmüştür.'),
  ('Bir tiyatro topluluğu Thornton Wilder\'ın "Bizim Şehir" oyununu yazarın özgün anlayışına sadık kalarak sahnelemek istediğinde dekor tasarımında nasıl bir yol izlemelidir?', 'Gerçekçi ev ve bahçe dekorlarından kaçınarak birkaç masa ve sandalye eşliğinde pandomimle izleyicinin hayal gücünü harekete geçirmelidir', ['Sahneye gerçek boyutta ahşap kasaba evleri, ağaçlar ve çalışan sokak lambaları inşa etmelidir', 'Tüm sahneyi dev led ekranlarla kaplayarak yirminci yüzyıl başı Amerikan arşiv görüntülerini yansıtmalıdır', 'Oyuncuları yüzlerini tamamen kapatan antik trajedi maskeleri ve ağır kadife pelerinlerle sahneye çıkarmalıdır'], 'Wilder, natüralist sahne kalabalığını reddederek boş sahne ve Sahne Amiri anlatıcısıyla evrensel bir tiyatrosallık kurmuştur.'),
  ('19. yüzyıl sonundan 20. yüzyıl ortasına uzanan Modern Batı Tiyatrosu\'nda Ibsen\'den Pirandello ve Artaud\'ya doğru yaşanan estetik evrim genel olarak nasıl özetlenebilir?', 'Sahneyi dış gerçekliğin kusursuz bir kopyası yapma çabasından, sahnenin kendi tiyatrosallığını ve öznel gerçekliği açığa vuran yanılsama karşıtı biçimlere yöneliş', ['Toplumsal ve felsefi sorunları tartışmaktan tamamen vazgeçerek yalnızca hafif müzikal eğlencelere geri dönüş', 'Manzum ve kafiyeli yazım kurallarını tüm Avrupa dillerinde yeniden zorunlu hale getiren neoklasik bir uyanış', 'Yönetmenlik kurumunun ortadan kaldırılarak sahne düzeninin yalnızca başrol oyuncularının kişisel tercihlerine bırakılması'], 'Modern tiyatro, gerçekçi-doğalcı "dördüncü duvar" yanılsamasıyla başlamış, ardından sembolizm, dışavurumculuk, Pirandello ve epik/avangart akımlarla bu yanılsamayı kırmıştır.'),
  ('Brecht\'in "Galileo\'nun Yaşamı" adlı oyununda Galileo\'nun Engizisyon tehdidi karşısında bilimsel gerçekleri geri çekmesi hangi temel etik sorunu tartışmaya açar?', 'Bilim insanının ürettiği bilginin toplumsal sonuçlarına karşı taşıdığı tarihsel ve ahlaki sorumluluğu', ['Orta Çağ astronomi aletlerinin optik açıdan yeterince gelişmemiş olmasının yarattığı teknik hataları', 'İtalyan şehir devletleri arasındaki gümrük vergilerinin üniversite bütçelerine verdiği zararı', 'Kilise korolarında çok sesli müziğin yasaklanmasının Rönesans sanatçılarına etkisini'], 'Özellikle Hiroşima\'ya atom bombası atılmasından sonra oyunu yeniden düzenleyen Brecht, bilimin iktidara boyun eğmesinin insanlığa ihanet olduğunu vurgular.'),
  ('Epik tiyatro ilkelerine göre sahnelenen bir oyunda sahne ışıklarının açıkta bırakılması, sahne değişimlerinin seyirci önünde yapılması ve şarkıların aksiyonu kesmesinin ortak işlevi nedir?', 'Tiyatronun bir yanılsama değil kurmaca bir gösterim olduğunu hatırlatarak dördüncü duvar illüzyonunu yıkmak', ['Tiyatro salonunun elektrik ve dekor giderlerini azaltarak bilet fiyatlarını ucuzlatmak', 'Sahne arkasındaki teknik görevlilerin de oyuncular kadar alkış almasını sağlamak', 'Tarihsel kostümlerin dikiş kusurlarını parlak beyaz ışık altında gizlemek'], 'Brechtçi sahnelemede tüm unsurlar (müzik, dekor, ışık, projeksiyon) birbirini taklit etmek yerine ayrışarak seyircinin uyanık kalmasını sağlar.'),
  ('Brecht tiyatrosunda oyuncunun bir eylemi gerçekleştirirken o eylemin ardındaki toplumsal konumu ve tavrı da somutlaştıran beden dili ve duruşuna ne ad verilir?', 'Gestus (Toplumsal Tavır)', ['Katarsis (Arınma)', 'Mimesis (Öykünme)', 'Peripeteia (Baht Dönüşü)'], '"Gestus", salt bireysel bir yüz ifadesi ya da jest değil, insanlar arasındaki toplumsal ve sınıfsal ilişkileri görünür kılan fiziksel-sesli tavırdır.'),
  ('Brecht\'in "Küçük Organon" adlı kuramsal metninde "Aristotelesçi Dramatik Tiyatro" ile "Epik Tiyatro" arasında kurduğu karşıtlıklardan hangisi doğrudur?', 'Dramatik tiyatroda insan değişmez ve verili kabul edilirken, epik tiyatroda insan hem değişen hem de değiştiren bir süreç olarak ele alınır', ['Dramatik tiyatroda her sahne kendi başına bağımsızken, epik tiyatroda sahneler birbirini zorunlu bir zincirle izler', 'Dramatik tiyatro seyirciyi gözlemci yapıp kararlara zorlarken, epik tiyatro seyirciyi olayın içine çekip etkinliğini tüketir', 'Dramatik tiyatro kanıtlar ve akla seslenirken, epik tiyatro telkinlerle yalnızca duygulara seslenir'], 'Brecht\'in ünlü karşılaştırma tablosunda dramatik tiyatro duygusal telkine ve değişmez insan doğasına, epik tiyatro ise akılcı kanıta ve tarihsel değişebilirliğe dayanır.'),
  ('Beckett\'in "Mutlu Günler" (Happy Days) adlı oyununda birinci perdede beline, ikinci perdede ise boynuna kadar toprağa gömülü olduğu halde neşeyle gevezelik etmeyi sürdüren Winnie karakteri neyi yansıtır?', 'Kaçınılmaz yok oluş ve ölüm karşısında insanın gündelik alışkanlıklara ve boş konuşmalara tutunarak sürdürdüğü trajikomik direnişi', ['Doğayla bütünleşerek modern şehir stresinden arınan alternatif tıp uygulamalarının başarısını', 'Maden göçüklerinde mahsur kalan işçilerin kurtarma ekiplerini beklerken kurdukları dayanışmayı', 'Tarım toplumlarında toprağın bereketini artırmak için yapılan bahar şenliği ritüellerini'], 'Çantasındaki diş fırçası ve ayna gibi küçük nesnelerle avunan Winnie, batmakta olan varoluşunun ortasında "Bugün de ne mutlu bir gün olacak!" diyerek absürt durumu özetler.'),
  ('Beckett\'in tiyatroyu en yalın sınırına indirgediği, yalnızca 35 saniye süren ve sahnede hiçbir oyuncu ya da söz bulunmaksızın sadece nefes sesi, çığlık ve çöplerle kurgulanan deneysel eseri hangisidir?', 'Soluğun (Breath / Nefes)', ['Not I (Ben Değil)', 'Adımlar', 'Rockaby'], '1969 tarihli "Breath" (Nefes), doğumu simgeleyen bir ağlama/çığlık, nefes alıp verme, ışığın çoğalıp azalması ve ikinci bir çığlıkla insan ömrünü 35 saniyeye sığdırır.'),
  ('Ionesco\'nun "Sandalyeler" adlı oyununda doksan yaşlarındaki yaşlı çiftin görünmez konuklar için sahneyi boş sandalyelerle doldurması ve tuttukları Hatip\'in dilsiz çıkması neyi vurgular?', 'Yaşamın anlamını özetleyecek nihai bir mesajın bulunmadığını, boşluğu ve iletişimsizliğin mutlaklığını', ['Yaşlı insanların emeklilik döneminde tiyatro salonu işletmeciliğinde yaşadıkları ticari başarısızlığı', 'Fransız Akademisi üyelerinin klasik hitabet sanatına verdikleri tarihsel önemi', 'Mobilya üretiminin seri imalata geçmesiyle el sanatlarının değer kaybetmesini'], 'Yaşlı çift tüm insanlığa mesajlarını iletecek Hatip\'e güvenerek intihar eder; ancak Hatip yalnızca anlamsız sesler çıkarır ve boş sandalyeler varoluşsal hiçliği somutlaştırır.'),
  ('Ionesco\'nun dört yüz yaşındaki Kral I. Bérenger\'nin krallığı çöküp çevresindeki her şey yok olurken ölüm gerçeğini kabullenme sürecini anlattığı varoluşsal oyunu hangisidir?', 'Kral Ölüyor', ['Susuzluk ve Açlık', 'Havada Yürüyen Adam', 'Yalnız Adam'], '"Kral Ölüyor" (Le Roi se meurt), insanın kendi ölümlülüğü karşısındaki inkar, korku ve nihai teslimiyet evrelerini törensel bir dille işler.'),
  ('Arthur Miller\'ın "Trajedi ve Sıradan İnsan" adlı ünlü makalesinde klasik Aristotelesçi trajedi geleneğine getirdiği temel kuramsal yenilik nedir?', 'Trajedinin yalnızca krallara ve soylulara özgü olmadığını; onurunu ve hak ettiği yeri korumak için hayatını ortaya koyan sıradan insanın da trajik yüceliğe ulaşabileceğini savunması', ['Modern çağda trajedi yazmanın artık imkansız olduğunu ve tiyatronun yalnızca politik belgeseller üretmesi gerektiğini ileri sürmesi', 'Trajik kahramanın hiçbir toplumsal baskı altında kalmadan tamamen genetik kusurları yüzünden yıkılması gerektiğini iddia etmesi', 'Seyircinin trajedi sonunda mutlak bir umutsuzluğa kapılarak yaşamdan el etek çekmesi gerektiğini savunması'], 'Miller, Willy Loman ve John Proctor gibi karakterlerle modern çağda "sıradan insanın trajedisi" kuramını temellendirmiştir.'),
  ('Edward Albee\'nin "Kim Korkar Hain Kurttan?" oyununda üniversite profesörü George ile karısı Martha\'nın genç konukları önünde "var olmayan hayali oğullarından" söz edip sabah olunca bu çocuğu "öldürmeleri" ne anlama gelir?', 'Çiftin kısırlıklarını ve başarısızlıklarını örtmek için yarattıkları ortak yaşam yalanını yıkarak çıplak gerçekle yüzleşmek zorunda kalmaları', ['Polis soruşturmasından kurtulmak için geçmişte işledikleri bir suçu konukların üzerine yıkmaya çalışmaları', 'Akademik terfi alabilmek amacıyla dekanın ailesine psikolojik şantaj uygulamaları', 'Üniversite kampüsündeki tiyatro kulübü için yazdıkları polisiye senaryoyu prova etmeleri'], 'George ve Martha\'nın gece boyu süren acımasız sözlü düellosu, sığındıkları "hayali çocuk" yanılsamasının yıkılmasıyla ve gerçek dünyadan duyulan korkunun kabulüyle son bulur.'),
  ('Harold Pinter\'ın penceresiz bir bodrum odasında tetikçilik emri bekleyen Ben ve Gus adlı iki kiralık katilin yemek asansöründen gelen tuhaf siparişlerle gerilmesini anlatan tek perdelik oyunu hangisidir?', 'Gitgel Dolap', ['Doğum Günü Partisi', 'Issız Toprak', 'Dağ Dili'], '"Gitgel Dolap" (The Dumb Waiter), görünmez bir üst otoriteye körü körüne itaat eden bireylerin sistem tarafından nasıl harcandığını gösteren absürt bir başyapıttır.'),
  ('Jean-Paul Sartre\'ın Antik Yunan\'daki Orestes mitini yeniden yazdığı "Sinekler" adlı oyunu, 1943\'te Nazi işgali altındaki Paris\'te sahnelendiğinde hangi felsefi-politik mesajı vermiştir?', 'İnsanın pişmanlık ve boyun eğme dayatan otoritelere baş kaldırarak kendi özgürlüğünü seçmesi ve eyleminin sorumluluğunu üstlenmesi gerektiğini', ['Antik Yunan tanrılarının insan kaderini doğuştan belirlediği ve bu yazgıya karşı çıkmanın anlamsız olduğunu', 'Savaş dönemlerinde aydınların siyasetten tamamen uzak durarak kırsal bölgelere çekilmesi gerektiğini', 'Suçluluk duygusunun toplumsal barışı sağlayan en kutsal erdem olarak korunması gerektiğini'], 'Sartre\'ın Orestes\'i, Jüpiter ve Aigisthos\'un halkı "suçluluk ve pişmanlık sinekleriyle" yönetmesine isyan ederek varoluşçu özgürlüğü ve direnişi seçer.'),
  ('Jean Genet\'nin "Balkon" adlı oyununda dışarıda devrim sürerken genelev müşterilerinin Piskopos, Yargıç ve General kılığına girmeleri iktidar olgusuna dair neyi gösterir?', 'Toplumsal otorite kurumlarının gücünü gerçeklikten değil, törensel kostümlerden, aynalardan ve kitlelerin inandığı simgesel yanılsamalardan aldığını', ['Devrim dönemlerinde askeri ve hukuki yöneticilerin güvenlik nedeniyle gizli sığınaklarda toplandığını', 'Fransız tiyatrosunda tarihsel kostüm tasarımının modern sivil giysilerden daha etkileyici olduğunu', 'Din, hukuk ve ordu temsilcilerinin halk ayaklanmalarını bastırmakta her zaman başarısız kaldığını'], 'Genet, iktidarın bir "görüntüler ve maskeler tiyatrosu" olduğunu, devrimcilerin bile iktidar imgelerine kapıldığında aynı yanılsama düzenini yeniden ürettiğini sergiler.'),
  ('Friedrich Dürrenmatt\'ın "Tiyatro Sorunları" adlı kuramsal yazısında çağdaş dünyada saf trajedi yerine yalnızca "grotesk ve trajikomedya" yazılabileceğini savunmasının temel gerekçesi nedir?', 'Modern bürokratik dünyada iktidarın ve suçun anonimleşmesiyle tek başına sorumlu trajik kahramanların ortadan kalkması', ['Çağdaş seyircinin çalışma saatlerinin uzunluğu yüzünden tiyatroda yalnızca gülmek istemesi', 'Antik Yunan mitolojisindeki tüm konuların önceki yüzyıllarda tamamen tüketilmiş olması', 'Sinema ve televizyon teknolojisinin dramatik sahneleri tiyatrodan daha ucuz üretmesi'], 'Dürrenmatt\'a göre modern devlet çarkında suçlular bile sorumluluğu üstlenmez ("Ben sadece görevimi yaptım" derler); bu yüzsüz dünyayı ancak grotesk komedya yakalayabilir.'),
  ('Max Frisch\'in "Andorra" adlı oyununda Yahudi olmadığı halde kasaba halkının önyargıları yüzünden Yahudi sanılan genç Andri\'nin sonunda bu kimliği kabullenip öldürülmesi neyi kanıtlar?', 'Toplumsal önyargıların ve ötekileştirici etiketlerin bireyin kimliğini zorla biçimlendiren ölümcül bir şiddet mekanizması olduğunu', ['Küçük dağ ülkelerinin komşu devletlerin askeri işgallerine karşı coğrafi olarak savunmasız kaldığını', 'Evlat edinilen çocukların biyolojik ailelerini bulamadıklarında psikolojik uyum sorunu yaşadığını', 'Orta Çağ loncalarındaki çıraklık sınavlarının genç zanaatkarlar için adaletsiz kurallar içerdiğini'], 'Frisch, "Kendine oyma put ve imge yapmayacaksın" ilkesinden hareketle insanların birbirine yapıştırdığı kalıp yargıların (antisemitizm, ırkçılık) yarattığı suçu sergiler.'),
  ('Peter Weiss\'ın Frankfurt\'ta görülen Auschwitz Nazi toplama kampı davalarının gerçek mahkeme tutanaklarından hiçbir duygusal süsleme katmadan oluşturduğu belgesel tiyatro başyapıtı hangisidir?', 'Soruşturma', ['Direnmenin Estetiği', 'Lusitan Öcüsü', 'Viet Nam Söylevi'], '1965 tarihli "Soruşturma" (Die Ermittlung), Dante\'nin Cehennem\'ini andıran 11 kantoluk yapısıyla belgesel tiyatronun en sarsıcı metinlerinden biridir.'),
  ('İngiliz yönetmen Peter Brook\'un çağdaş sahne estetiğini "Ölücül, Kutsal, Kaba ve Dolaysız Tiyatro" başlıklarıyla incelediği ve "Bir mekanı alıp oradan geçen birini başka biri izlerken tiyatro başlamış olur" dediği ünlü kuram kitabı hangisidir?', 'Boş Alan', ['Tiyatro ve İkizi', 'Açık Yapıt', 'Ezilenlerin Tiyatrosu'], 'Peter Brook\'un 1968 tarihli "Boş Alan" (The Empty Space) adlı kitabı, 20. yüzyılın en etkili sahneleme ve tiyatro kuramı metinlerinden biridir.'),
  ('Sławomir Mrożek\'in "Tango" adlı oyununda kuralsız ve bohem bir ev ortamında büyüyen genç Arthur\'un anne-babasına karşı katı gelenekleri geri getirmeye çalışırken kaba güç temsilcisi Edek\'e yenilmesi neyi simgeler?', 'Değerlerin tümüyle aşındığı kaotik toplumlarda biçimsel düzen arayışının sonuçsuz kalıp sonunda kaba ve ilkel diktatörlüğe zemin hazırlamasını', ['Arjantin halk danslarının Doğu Avrupa salon müziği üzerindeki kültürel etkisini', 'Kuşaklar arası çatışmanın her zaman gençlerin sanatsal zaferiyle sonuçlandığını', 'Üniversiteli tıp öğrencilerinin geleneksel aile evliliklerine duyduğu romantik özlemi'], 'Mrożek, avangart kuralsızlığın yarattığı boşluğu doldurmaya çalışan entelektüelin kaba zorba (Edek) karşısındaki trajikomik yenilgisini "La Cumparsita" tangosu eşliğinde gösterir.'),
  ('Alman yazar Heiner Müller\'in Brecht sonrası postmodern tiyatronun dönüm noktası sayılan ve Shakespeare\'in başyapıtını yalnızca birkaç sayfalık parçalı, yoğun imgelere indirgediği metni hangisidir?', 'Hamletmakinesi', ['Görev', 'Kuartet', 'Germania Ölüm Berlin\'de'], 'Heiner Müller\'in 1977 tarihli "Hamletmakinesi" (Die Hamletmaschine), doğrusal öyküyü ve karakter bütünlüğünü parçalayarak "postdramatik tiyatro"nun temel metinlerinden biri olmuştur.'),
  ('Alman tiyatro kuramcısı Hans-Thies Lehmann\'ın 1999\'da kavramsallaştırdığı "Postdramatik Tiyatro" anlayışının geleneksel ve modern dramatik tiyatrodan en belirgin farkı nedir?', 'Edebi metnin sahne üzerindeki hiyerarşik üstünlüğünü kaldırarak metni ışık, ses, beden, mekan ve zamanla eşit düzeyde bir performans öğesine dönüştürmesi', ['Yalnızca 19. yüzyıl gerçekçi salon komedyalarının yazarın noktasına virgülüne dokunulmadan sahnelenmesini savunması', 'Sahnedeki tüm görsel ve işitsel araçları yasaklayarak tiyatroyu radyo tiyatrosu biçiminde karanlıkta sunması', 'Oyunların mutlaka giriş-gelişme-sonuç sırasına ve klasik üç birlik kuralına uymasını şart koşması'], 'Lehmann\'a göre Robert Wilson, Heiner Müller ve Pina Bausch gibi sanatçılarla gelişen postdramatik sahnede kurmaca bir öykünün temsili yerine sahnesel varoluş ve performans öne çıkar.'),
  ('1990\'lı yıllarda Sarah Kane ("Psikoz 4.48", "Patlamış") ve Mark Ravenhill ile İngiltere\'de öne çıkan "Suratına Tiyatro" (In-Yer-Face Theatre) akımının temel sahne stratejisi nedir?', 'Şiddet, istismar ve ruhsal yıkım gibi tabu konuları sansürsüz ve sarsıcı bir yakınlıkla seyircinin konfor alanına sokarak ahlaki uyuşukluğu kırmak', ['Tarihsel krallık savaşlarını görkemli saray dekorları ve klasik bale gösterileriyle estetize ederek sunmak', 'Yalnızca çocuk izleyicilere yönelik eğitici masalları kukla ve gölge oyunu teknikleriyle canlandırmak', 'Duygusal çatışmalardan tamamen kaçınarak günlük gazete bulmacalarını seyirciyle birlikte çözmek'], 'Antonin Artaud\'nun Vahşet Tiyatrosu mirasını çağdaş kent travmalarına taşıyan bu akım, izleyiciyi sarsarak duygusal ve etik bir yüzleşmeye zorlar.'),
  ('Brecht\'in "Epik Tiyatrosu" ile Beckett ve Ionesco\'nun "Absürt Tiyatrosu" sahne yanılsamasını (illüzyonu) kırma noktasında birleşseler de hangi temel felsefi noktada keskin biçimde ayrılırlar?', 'Epik tiyatro toplumsal düzenin akıl ve eylemle değiştirilebileceğine inanırken, absürt tiyatro insan varoluşunun değişmez uyumsuzluğunu ve dilin çaresizliğini yansıtır', ['Epik tiyatro yalnızca bireysel bilinçaltı rüyalarını işlerken, absürt tiyatro somut ekonomik kalkınma planları sunar', 'Epik tiyatro seyircinin sahneyle duygusal özdeşleşme kurmasını isterken, absürt tiyatro dört duvar doğalcılığını zorunlu kılar', 'Epik tiyatro yazılı metni tamamen reddederken, absürt tiyatro yalnızca tarihsel mahkeme belgelerini kullanır'], 'Her iki akım da gerçekçi yanılsamaya karşıdır; ancak Marksist diyalektiğe dayanan Brecht dünyayı değiştirmeyi hedeflerken, Beckett ve Ionesco kozmik ve dilsel açmazı sergiler.'),
  ('Modern Batı Tiyatrosu\'nda Nora\'nın kapıyı çarpıp çıkışından ("Bir Bebek Evi") Vladimir ile Estragon\'un yerlerinden kıpırdayamayışına ("Godot\'yu Beklerken") uzanan çizgi dramatik eylem açısından neyi gösterir?', 'Bireyin toplumu ve kaderini eylemle dönüştürebileceğine duyulan 19. yüzyıl güveninin, iki dünya savaşı sonrasında yerini eylemsizlik ve varoluşsal kuşkuya bırakmasını', ['Tiyatro yazarlarının kapalı ev içi mekanlardan tamamen vazgeçerek yalnızca stadyum büyüklüğündeki açık hava sahnelerine yönelmesini', 'Kadın karakterlerin tiyatro metinlerinden çıkarılarak yalnızca iki kişilik erkek oyunlarının yazılması kuralının yerleşmesini', 'Avrupa tiyatrosunun felsefi sorunları terk edip yalnızca vodvil ve hafif bulvar komedyalarına geri dönmesini'], '1879\'da Nora\'nın kararlı eylemiyle açılan modern dram, 20. yüzyıl ortasında "Gidelim! / Gidemeyiz, Godot\'yu bekliyoruz" diyen eylemsizlikle modernizmin kırılmasını özetler.'),
  ('Şinasi\'nin "Şair Evlenmesi" eseri yapı ve üslup açısından değerlendirildiğinde geleneksel Türk tiyatrosu ile Batı tiyatrosunu nasıl birleştirir?', 'Orta oyunu ve Karagöz\'deki tiplemeleri Batılı komedya kurgusu ve yazılı metin düzeniyle kaynaştırır', ['Meddah geleneğindeki tek kişilik anlatımı trajedinin üç birlik kuralına bağlı kalarak manzum biçimde sunar', 'Köy seyirlik oyunlarındaki ritüelleri epik tiyatronun yabancılaştırma efektiyle bir araya getirir', 'Karagöz perdesindeki tasvirleri romantik dramın acıklı ölüm sahneleriyle sentezler'], 'Eserde Ziba Dudu, Ebullaklaka ve Batak Ese gibi mahalle tipleri geleneksel orta oyunundan izler taşırken, olay örgüsü ve yazılı sahne tekniği Moliere tarzı Batılı komedyaya dayanır.'),
  ('Namık Kemal\'in tiyatro eserleri arasında "Celaleddin Harzemşah"ı diğer oyunlarından ayıran en belirgin sahneleme özelliği nedir?', 'Sahnelenmekten ziyade okunmak amacıyla on beş perde halinde çok uzun kurgulanmış olması', ['Tamamıyla hece ölçüsü ve uyaklı dizelerle kaleme alınmış tek manzum komedya olması', 'Geleneksel orta oyunundaki "meydan" düzenine göre dekor kullanılmadan tasarlanması', 'Kadın karakterlere hiç yer verilmeden yalnızca savaş meydanındaki askerleri konu alması'], 'Namık Kemal diğer beş oyununu sahnelenmek üzere yazarken, Moğol istilasına karşı İslam birliğini savunan Celaleddin Harzemşah\'ı okunmak üzere 15 perde olarak tasarlamıştır.'),
  ('Namık Kemal\'in sadakatsiz bir eş olan Dilruba\'nın entrikalarını ve Kırım Savaşı\'ndan dönen denizci kocasının trajedisini işlediği eseri hangisidir?', 'Akif Bey', ['Kara Bela', 'Gülnihal', 'Celaleddin Harzemşah'], '"Akif Bey" oyununda Sinop Baskını\'nda öldü sanılan deniz subayı Akif Bey\'in karısı Dilruba\'nın ihaneti ve sonunda yaşanan kanlı hesaplaşma anlatılır.'),
  ('Namık Kemal\'in konusu Osmanlı veya İslam coğrafyası dışında, Hint sarayında geçen ve hadım ağası Behrever\'in ihtirasını işleyen trajedisi hangisidir?', 'Kara Bela', ['Akif Bey', 'Gülnihal', 'Zavallı Çocuk'], '"Kara Bela", Babürlü Hint padişahının kızı Behrever Banu ile vezir oğlu Hüsrev\'in aşkını ve saray haremindeki zenci hadım Ahşid\'in yarattığı felaketi konu alır.'),
  ('Ahmet Vefik Paşa\'nın Moliere\'in "Cimri" (L\'Avare) adlı ünlü karakter komedyasından yerli hayata uyarladığı eserin adı aşağıdakilerden hangisidir?', 'Azarya', ['Yorgaki Dandini', 'Kocalar Mektebi', 'Kadınlar Mektebi'], 'Ahmet Vefik Paşa, Moliere\'in "L\'Avare" (Cimri) adlı eserini Yahudi bir sarraf tiplemesi üzerinden "Azarya" adıyla Osmanlı toplumuna uyarlamıştır.'),
  ('Moliere\'in "Scapin\'in Dolapları" adlı komedyasını "Ayyar Hamza" adıyla Osmanlı yaşamına başarıyla uyarlayan Tanzimat Dönemi tiyatro yazarı kimdir?', 'Direktör Ali Bey', ['Ahmet Vefik Paşa', 'Feraizcizade Mehmet Şakir', 'Ebüzziya Tevfik'], 'Tiyatro gelişimine büyük emek veren Direktör Ali Bey, Moliere\'in "Les Fourberies de Scapin" eserini "Ayyar Hamza" adıyla adapte etmiş, ayrıca "Kokona Yatıyor" gibi telif oyunlar yazmıştır.'),
  ('Tanzimat\'ın ikinci döneminde Abdülhak Hamit Tarhan ve Recaizade Mahmut Ekrem gibi sanatçıların yazdığı tiyatroların birinci dönem tiyatrolarından en önemli farkı nedir?', 'Siyasi baskı ve sansür ortamı nedeniyle sahnelenmek için değil okunmak için ağır bir dille yazılmaları', ['Halkı eğitmek amacıyla sade bir Türkçe kullanılarak mahalle kahvehanelerinde doğaçlama sergilenmeleri', 'Konularını yalnızca güncel esnaf sorunlarından seçerek komedya türünde yoğunlaşmaları', 'Aruz ve hece ölçüsünü tamamen reddedip yalnızca günlük konuşma diliyle kısa skeçler üretmeleri'], 'İstibdat döneminin etkisi ve Gedikpaşa Tiyatrosu\'nun yıktırılmasıyla II. dönem Tanzimat tiyatroları sahne tekniğinden uzaklaşmış, okunmak üzere bireysel/tarihsel temalarla ve ağır bir dille yazılmıştır.'),
  ('Musahipzade Celal\'in Lale Devri\'nden sonra esnaf loncalarını denetleyen belediye reisi ve başkadılık makamındaki Savleti Efendi\'nin cinlere-perilere olan aşırı merakını işlediği müzikli komedyası hangisidir?', 'İstanbul Efendisi', ['Balaban Ağa', 'Yedekçi', 'İtaat İlamı'], '"İstanbul Efendisi" oyununda kızı Esma\'yı evlendirmek için falcılara ve cinlere başvuran Savleti Efendi\'nin gülünç durumu ve eski İstanbul\'un renkli yaşamı anlatılır.'),
  ('Musahipzade Celal\'in tiyatro anlayışı değerlendirildiğinde aşağıdakilerden hangisi yazarın oyunlarının ortak özelliklerinden biri olarak gösterilebilir?', 'Bireysel psikolojik çözümlemelerden ziyade geleneksel seyirlik oyunlardan beslenen toplumsal tipler ve kolektif tablo düzeni kurması', ['Batı\'daki absürt tiyatronun etkisiyle zaman ve mekan kavramlarını tamamen soyutlayarak bilinçaltı çatışmalarını öne çıkarması', 'Yalnızca Cumhuriyet sonrası sanayileşme ve köyden kente göç sorunlarını trajik bir üslupla sahneye taşıması', 'Oyunlarında müziği, dansı ve görsel halk kültürünü reddederek yalnızca felsefi monologlara yer vermesi'], 'Musahipzade Celal, karakter derinliğinden çok orta oyunu geleneğine yakın toplumsal tipler yaratmış; eski İstanbul\'un lonca, mahalle ve konak yaşamını müzikli-danslı renkli tablolar halinde hicvetmiştir.'),
  ('Darülbedayi\'de 20 Ocak 1916 tarihinde sahnelenen ilk oyun olan ve Hüseyin Suat Yalçın tarafından Fransızcadan uyarlanan eserin adı nedir?', 'Çürük Temel', ['Baykuş', 'Hisse-i Şayia', 'Pençe'], 'Darülbedayi\'nin Tepebaşı Kışlık Tiyatrosu\'nda perde açtığı ilk temsil, Hüseyin Suat Yalçın\'ın Emile Fabre\'dan uyarladığı "Çürük Temel" adlı oyundur; telif ilk oyun ise Halit Fahri Ozansoy\'un "Baykuş"udur.'),
  ('Muhsin Ertuğrul\'un 1935 yılında İstanbul Şehir Tiyatroları bünyesinde geleceğin bilinçli seyircisini ve sanatçısını yetiştirmek amacıyla başlattığı öncü uygulama aşağıdakilerden hangisidir?', 'Kurumsal çocuk tiyatrosu temsillerini başlatması', ['Gezici köy kukla çadırları kurdurması', 'Yalnızca opera ve bale eserlerine yer vermesi', 'Geleneksel meddahlık okulunu yeniden açması'], 'Muhsin Ertuğrul, 1935\'te M. Kemal Küçük\'ün "Çocuklara İlk Tiyatro Dersi" adlı oyunuyla Türkiye\'de düzenli ve kurumsal Çocuk Tiyatrosu çalışmalarını başlatmıştır.'),
  ('Cumhuriyet\'in ilk yıllarında Muhsin Ertuğrul\'un yerli yazarları teşvik etmek amacıyla Darülbedayi\'de uyguladığı repertuvar politikasının Türk edebiyatına etkisi ne olmuştur?', 'Nazım Hikmet, Necip Fazıl, Reşat Nuri ve Vedat Nedim Tör gibi şair ve romancıların tiyatro metinleri yazmasını sağlamıştır', ['Edebiyatçıların tiyatrodan uzaklaşarak yalnızca gazete fıkrası ve makale türlerine yönelmesine yol açmıştır', 'Aruz ölçüsüyle trajedi yazma zorunluluğu getirerek klasik divan şiiri kalıplarını sahnede canlandırmıştır', 'Yerli oyunların sahnelenmesini on yıl süreyle durdurarak yalnızca çeviri vodvillere yer vermiştir'], 'Muhsin Ertuğrul, yerli oyun açığını kapatmak için dönemin güçlü kalemlerini tiyatro yazmaya özendirmiş; böylece Kafatası, Tohum, Taş Parçası gibi pek çok eser sahneye taşınmıştır.'),
  ('"Keşanlı Ali Destanı"nda projeksiyonla sahneye başlıklar yansıtılması, oyuncuların doğrudan seyirciye seslenmesi ve araya şarkıların girmesi hangi tiyatro tekniğinin bir gereğidir?', 'Seyircinin oyuna duygusal olarak kapılmasını önleyip eleştirel düşünmesini sağlayan yabancılaştırma efektinin', ['Seyirciyi sahnedeki acıklı olaylarla özdeşleştirerek ruhsal arınmaya (katarsis) ulaştırma ilkesinin', 'Zaman, mekan ve olay birliğini koruyarak sahnede tam bir gerçeklik yanılsaması yaratma kuralının', 'Bilinçaltındaki bastırılmış korkuları gerçeküstücü sembollerle dışavurma yönteminin'], 'Epik (göstermeci) tiyatroda yabancılaştırma etmeni (Verfremdungseffekt), seyircinin sahnedekinin bir oyun olduğunu unutmamasını ve toplumsal çarpıklıkları akıl süzgecinden geçirmesini amaçlar.'),
  ('Haldun Taner\'in Boğaziçi\'ndeki bir mahallede Sadettin Bey\'in işlettiği eski bir eczane etrafında değişen toplumsal değerleri ve kapitalistleşme karşısında eriyen dürüstlüğü anlattığı yanılsamacı (klasik kurgulu) oyunu hangisidir?', 'Fazilet Eczanesi', ['Eşeğin Gölgesi', 'Ayışığında Şamata', 'Dışardakiler'], '1960 tarihli "Fazilet Eczanesi", Haldun Taner\'in epik tiyatroya geçmeden önceki "yanılsamacı/dramatik" döneminin en olgun eserlerinden biri olup eski İstanbul terbiyesiyle yeni rant düzeninin çatışmasını işler.'),
  ('Haldun Taner\'in Abdalya adlı hayali bir ülkede bir eşeğin gölgesinin kiralanması yüzünden çıkan anlaşmazlığın tüm ülkeyi ikiye bölen siyasi ve mezhepsel bir kavgaya dönüşmesini hicvettiği oyunu hangisidir?', 'Eşeğin Gölgesi', ['Günün Adamı', 'Ve Değirmen Dönerdi', 'Timsah'], 'Antik Yunan yazarı Lukianos ve Alman yazar Wieland\'da da rastlanan motiften hareketle yazılan "Eşeğin Gölgesi", demagoji, basın, hukuk ve siyaset yozlaşmasını epik-masalsı biçimde taşlar.'),
  ('Haldun Taner\'in dürüst bir ekonomi profesörünün siyasete atıldıktan sonra parti çıkarları ve bürokratik yozlaşma karşısında yaşadığı hayal kırıklığını işlediği ilk dönem oyunu hangisidir?', 'Günün Adamı', ['Astronot Niyazi', 'Ha Bu Diyar', 'Yâr Bana Bir Eğlence'], '1953\'te Şehir Tiyatroları\'nda provaları yapılırken valilikçe sahnelenmesi engellenen "Günün Adamı", dürüst bilim insanı ile çıkarcı siyaset dünyası arasındaki çatışmayı ele alır.'),
  ('Cevat Fehmi Başkut\'un yıllar önce Amerika\'ya göç etmiş zengin bir Ermeni iş insanının doğduğu memleketi Elazığ\'a kardeşini aramaya gelmesi ve fırsatçıların sahte kardeşler çıkarmasını işlediği komedyası hangisidir?', 'Harput\'ta Bir Amerikalı', ['Büyük Şehir', 'Ayarsızlar', 'Hacı Kaptan'], '"Harput\'ta Bir Amerikalı"da milyoner Abraham Maderus\'un özlemini çektiği memleketinde karşılaştığı Amerikan hayranlığı, para hırsı ve kültürel yozlaşma mizahi bir dille eleştirilir.'),
  ('II. Meşrutiyet ve Milli Edebiyat yıllarında "Binnaz" adlı aruz ölçüsüyle yazılmış manzum oyunuyla büyük ün kazanan şair ve yazar kimdir?', 'Yusuf Ziya Ortaç', ['Enis Behiç Koryürek', 'Orhan Seyfi Orhon', 'Ömer Seyfettin'], 'Beş Hececiler\'den Yusuf Ziya Ortaç\'ın Lale Devri İstanbul\'unda geçen ve 1919\'da Darülbedayi\'de sahnelenen "Binnaz" adlı eseri, aruzla yazılmış en başarılı manzum piyeslerden biri sayılmıştır.'),
  ('Reşat Nuri Güntekin\'in din istismarını ve resmi nikah-dini nikah (boşama) kurallarının çıkarcılar tarafından nasıl kötüye kullanıldığını mizahi bir dille eleştirdiği komedyası hangisidir?', 'Hülleci', ['Eski Şarkı', 'İstiklal', 'Bir Köy Öğretmeni'], '"Hülleci", öfkelenip karısını üç talakla boşayan bir adamın pişman olması üzerine para karşılığı tutulan uyanık bir hüllecinin yarattığı komik ve düşündürücü olayları anlatır.'),
  ('Necip Fazıl Kısakürek\'in Muhsin Ertuğrul tarafından başrolü de oynanan "Bir Adam Yaratmak" adlı eserinin merkezinde yer alan temel çatışma nedir?', 'Yazdığı tiyatro oyunundaki kurgusal felaketlerin kendi gerçek hayatında da birebir yaşanmasıyla sarsılan bir yazarın kader ve irade sorgulaması', ['Kurtuluş Savaşı yıllarında Anadolu\'daki bir telgraf memurunun işgal kuvvetlerine karşı verdiği istihbarat mücadelesi', 'Büyük kente göç eden yoksul bir ailenin apartman kapıcılığı yaparken karşılaştığı sınıfsal aşağılanmalar', 'Osmanlı\'nın son döneminde batılılaşmayı yanlış anlayan züppe bir gencin servetini kumarda kaybetmesi'], '"Bir Adam Yaratmak"ta oyun yazarı Hüsrev, "Ölüm Korkusu" adlı piyesinde kurguladığı kaza ve delirme motiflerinin kendi hayatında gerçekleşmesiyle insanın yaratma iddiası ve kader karşısındaki acizliğini sorgular.'),
  ('1932 yılında Türkiye ve İran arasındaki dostluğu pekiştirmek amacıyla Atatürk\'ün isteği üzerine yazılan ve Adnan Saygun tarafından bestelenen ilk ulusal Türk operası "Özsoy"un librettosu (metni) kime aittir?', 'Münir Hayri Egeli', ['Behçet Kemal Çağlar', 'Ahmet Kutsi Tecer', 'Sabahattin Ali'], 'İran Şahı Rıza Pehlevi\'nin Türkiye ziyareti onuruna sahnelenen "Özsoy" operasının librettosunu Münir Hayri Egeli yazmış, müziğini Ahmet Adnan Saygun bestelemiştir.'),
  ('Ahmet Kutsi Tecer\'in ABD\'de "The Neighborhood" adıyla da sahnelenen "Köşebaşı" adlı eserini Cumhuriyet tiyatrosunda özgün kılan biçimsel özellik nedir?', 'Geleneksel orta oyunundaki mahalle dekoru ve açık biçim anlayışını modern sahne tekniğiyle kaynaştırarak sıradan bir günün kesitini sunması', ['Tamamıyla aruz ölçüsü kullanılarak Yunan mitolojisindeki tanrıların çatışmasını Anadolu\'ya uyarlaması', 'Tek kişilik bir meddah gösterisi şeklinde kurgulanıp hiçbir yan karaktere sahnede yer vermemesi', 'Bilim kurgu öğeleri kullanarak gelecekteki mekanikleşmiş insan ilişkilerini distopik bir dille anlatması'], '"Köşebaşı", belirgin bir başkahraman veya entrika yerine bir İstanbul mahallesinin doğumdan ölüme uzanan günlük ritmini geleneksel seyirlik oyun estetiğiyle sahneye taşımıştır.'),
  ('Nazım Hikmet\'in 1932\'de Darülbedayi\'de Muhsin Ertuğrul yönetiminde sahnelenen, kapitalist sistemde bilimsel bir buluşun (verem aşısının) ticari çıkara kurban edilişini eleştiren oyunu hangisidir?', 'Kafatası', ['Yusuf ile Menofis', 'Ferhad ile Şirin', 'İnek'], '"Kafatası" oyununda Dalbanezo ülkesinde verem aşısını bulan Doktor Dalbanezo\'nun tröstler ve ilaç tekelleri tarafından nasıl ezildiği çarpıcı bir sahne diliyle anlatılır.'),
  ('Şemsettin Sami\'nin Endülüs Emevi Devleti tarihinden esinlenerek kaleme aldığı tiyatro eseri aşağıdakilerden hangisidir?', 'Seydi Yahya', ['Gave', 'Besa yahut Ahde Vefa', 'Ecel-i Kaza'], 'Şemsettin Sami; Arnavut geleneklerini anlatan "Besa yahut Ahde Vefa", Şehname\'den alınan "Gave" ve Endülüs tarihini işleyen "Seydi Yahya" adlı üç önemli Tanzimat tiyatrosunun yazarıdır.'),
  ('Recaizade Mahmut Ekrem\'in "Binbir Gündüz" masallarından esinlenerek yazdığı, Maraş kadısı Azmi Efendi\'nin kurduğu tuzağa kendisinin düşmesini anlatan başarılı komedyası hangisidir?', 'Çok Bilen Çok Yanılır', ['Vuslat yahut Süreksiz Sevinç', 'Afife Anjelik', 'Atala yahut Amerikan Vahşileri'], 'Recaizade Mahmut Ekrem\'in ölümünden sonra yayımlanan ve sahnelenen "Çok Bilen Çok Yanılır" adlı eseri, kıskanç ve kurnaz kadı Azmi Efendi\'nin gülünç durumunu işleyen tek komedyasıdır.'),
  ('Turgut Özakman\'ın Reşat Nuri Güntekin\'in "Değirmen" adlı romanından sahneye uyarladığı, olmayan bir depremin bürokratik telaşla varmış gibi büyütülmesini hicveden oyunu hangisidir?', 'Sarıpınar 1914', ['Deliler', 'Kanaviçe', 'Paramparça'], 'Turgut Özakman, Reşat Nuri\'nin "Değirmen" romanını "Sarıpınar 1914" adıyla açık biçim (göstermeci) tiyatro tekniğinden yararlanarak sahneye uyarlamıştır.'),
  ('Turgut Özakman\'ın hapishaneden kaçan dört mahkumun genç bir kızı rehin almaları üzerinden suçun bireysel değil toplumsal nedenlerini sorguladığı dramı hangisidir?', 'Duvarların Ötesi', ['Pembe Evin Kaderi', 'Bulvar', 'Kardeş Payı'], '"Duvarların Ötesi" oyununda mahkumlarla rehin alınan öğretmen adayı genç kız arasındaki gerilimli diyaloglar aracılığıyla toplumun suçlu yaratmadaki payı irdelenir.'),
  ('Turgut Özakman\'ın tiyatro yazarlığında 1960\'ların sonundan itibaren yaşanan biçimsel dönüşüm aşağıdakilerden hangisidir?', 'İbsen tarzı kapalı biçim aile dramlarından geleneksel Türk tiyatrosunun açık biçim olanaklarını kullanan göstermeci oyunlara yönelmesi', ['Güncel konuşma dilini tamamen bırakarak yalnızca Divan şiiri mazmunlarıyla örülü aruzlu trajediler yazması', 'Toplumsal konuları terk edip yalnızca Antik Yunan mitolojisindeki tanrıların savaşlarını sahneye taşıması', 'Oyunlarında diyalog kullanımına son vererek yalnızca sessiz pandomim metinleri üretmesi'], 'Özakman; Pembe Evin Kaderi, Ocak, Duvarların Ötesi gibi yanılsamacı (kapalı biçim) oyunlardan sonra Sarıpınar 1914, Fehim Paşa Konağı ve Bir Şehnaz Oyun ile açık biçim/geleneksel senteze yönelmiştir.'),
  ('Güngör Dilmen\'in Karamanlı bir köy kadını olan "Zehra"nın üzerine kuma getirilmesine karşı çocuklarıyla birlikte ölüme giderek gösterdiği trajik başkaldırıyı anlattığı oyunu hangisidir?', 'Kurban', ['Ben Anadolu', 'İttihat ve Terakki', 'Devlet ve İnsan'], 'Euripides\'in "Medeia" trajedisiyle de paralellik taşıyan "Kurban" oyununda Zehra, kocası Mahmut\'un genç Gülsüm\'ü kuma getirmesine razı olmaz ve töreye karşı sarsıcı bir trajediyle direnir.'),
  ('Güngör Dilmen\'in Kibele\'den Kurtuluş Savaşı\'ndaki Halide Edip\'e kadar Anadolu topraklarında yaşamış on altı farklı kadını tek bir kadın oyuncunun canlandırması için yazdığı eseri hangisidir?', 'Ben Anadolu', ['Bağdat Hatun', 'Troya İçinde Vurdular Beni', 'Hasan Sabbah'], 'Yıldız Kenter\'in unutulmaz yorumuyla yurt içinde ve yurt dışında yüzlerce kez sahnelenen "Ben Anadolu" (Söyleşi), binlerce yıllık Anadolu tarihini kadın kahramanların ağzından aktarır.'),
  ('Güngör Dilmen\'in İlhanlı Devleti döneminde iktidar hırsıyla entrikalar çeviren güçlü bir kadının yükselişini ve çöküşünü anlattığı tarihsel oyunu hangisidir?', 'Bağdat Hatun', ['Ak Tanrılar', 'Midas\'ın Altınları', 'Mithat Paşa'], '"Bağdat Hatun", 14. yüzyılda İlhanlı sarayında geçen ve Güngör Dilmen\'in iktidar tutkusu ile kadın kimliğini tarihsel düzlemde birleştirdiği güçlü bir dramdır.'),
  ('Güngör Dilmen\'in "Ak Tanrılar" adlı oyununda Aztek İmparatoru Montezuma ile İspanyol istilacı Cortes arasındaki karşılaşma üzerinden sorgulanan temel tema nedir?', 'Dinsel kehanetlere ve kaderciliğe teslim olan bir uygarlığın sömürgeci silah gücü karşısında yıkılışı', ['Orta Asya Türk boylarının kuraklık nedeniyle batıya göç ederken karşılaştığı doğa engelleri', 'Sanayi Devrimi sonrasında İngiltere\'deki maden işçilerinin sendikal hak arayışları', 'Osmanlı donanmasının Akdeniz\'deki korsanlarla yürüttüğü deniz savaşları'], '"Ak Tanrılar" oyununda İspanyol işgalcileri efsanedeki "ak tanrılar" sanarak direnmeyen Aztek yöneticilerinin yanılgısı ve Batı sömürgeciliğinin acımasızlığı işlenir.'),
  ('Orhan Asena\'nın sadrazam Alemdar Mustafa Paşa ile yeniçeri ocağı ve saray gericiliği arasındaki kanlı iktidar mücadelesini anlattığı tarihsel oyunu hangisidir?', 'Tohum ve Toprak', ['Ya Devlet Başa Ya Kuzgun Leşe', 'Kocaoğlan', 'Gecenin Sonu'], '"Tohum ve Toprak" (Alemdar Paşa), III. Selim ve II. Mahmut dönemlerindeki yenileşme sancılarını ve Alemdar Mustafa Paşa\'nın trajik sonunu işler.'),
  ('Orhan Asena\'nın "Tanrılar ve İnsanlar", "Hürrem Sultan", "Atçalı Kel Mehmet" ve "Şili\'de Av" gibi farklı coğrafya ve dönemlerde geçen oyunlarını birleştiren ana izlek nedir?', 'Bireyin üstün güçler, korku, baskı rejimleri ve iktidar tutkusu karşısındaki trajik direnişi ve irade sınavı', ['Geleneksel İstanbul konaklarındaki yanlış batılılaşma ve Fransız mürebbiye özentisinin gülünç sonuçları', 'Kırsal kesimden büyük şehirlere göç eden mevsimlik tarım işçilerinin barınma sorunları', 'Modern tıp fakültelerinde görev yapan hekimlerin mesleki rekabetleri ve bürokratik atamaları'], 'Orhan Asena, konusunu mitolojiden, Osmanlı tarihinden ya da Latin Amerika\'dan (Şili\'de Av) alsa da daima "korku, iktidar ve başkaldıran insan" trajedisini merkezde tutmuştur.'),
  ('Turan Oflazoğlu\'nun Mimar Sinan\'ın Süleymaniye ve Selimiye camilerini inşa ederken yaşadığı sanatsal yaratım sancısını ve kusursuzluk arayışını işlediği oyunu hangisidir?', 'Sinan', ['Yine Bir Gülnihal', 'Cem Sultan', 'Bizans Düştü'], '"Sinan" adlı oyunda büyük mimarın hem maddeye biçim verme mücadelesi hem de iktidar ve çağının insanlarıyla yaşadığı içsel hesaplaşma şiirsel bir dille anlatılır.'),
  ('Turan Oflazoğlu\'nun Atina demokrasisinin yozlaştığı bir dönemde düşünce özgürlüğü ve erdem uğruna baldıran zehri içerek ölüme yürüyen filozofu konu aldığı oyunu hangisidir?', 'Sokrates Savunuyor', ['Gardiyan', 'Dörtbaşı Mamur Şahin Çakırpençe', 'Güzellik ile Aşk'], '"Sokrates Savunuyor", Oflazoğlu\'nun evrensel düşünce tarihine yönelerek hakikat tutkusu ile çoğunluk tahakkümü arasındaki çatışmayı sergilediği felsefi bir trajedidir.'),
  ('Orhan Asena ile Turan Oflazoğlu\'nun tarihsel tiyatro anlayışları karşılaştırıldığında her iki yazarın da ortaklaştığı en belirgin estetik özellik nedir?', 'Tarihsel olayları kuru bir kronoloji olarak değil, insan doğasındaki evrensel iktidar hırsı ve psikolojik çatışmaları açığa çıkaran bir trajedi zemini olarak kullanmaları', ['Osmanlı padişahlarını geleneksel Karagöz perdesindeki Hacivat ve Beberuhi gibi güldürü tiplerine indirgemeleri', 'Tarihi metinlerdeki vakayinameleri hiçbir kurgusal değişiklik yapmadan belgesel haber bülteni üslubuyla okumaları', 'Sahne dilinde yalnızca Orta Asya Göktürk Türkçesinin söz varlığını kullanarak anlaşılması güç metinler üretmeleri'], 'Hem Orhan Asena hem Turan Oflazoğlu, Shakespeareyen trajedi geleneğinden beslenerek tarihi kişiliklerin iç dünyalarındaki korku, iktidar ve vicdan yarılmalarını derinlikli bir dille işlemiştir.'),
  ('Necati Cumalı\'nın Yörük obasında çocuğu olmayan Fatma\'nın töre baskısına direnişini ve sonunda bebeğini göç yolunda kartallara kaptırmasını şiirsel bir dille anlattığı dramı hangisidir?', 'Boş Beşik', ['Mine', 'Vur Emri', 'Gömü'], '1949\'da sahnelenen "Boş Beşik", Anadolu kadınının doğurganlık beklentisi ve aşiret töresi karşısındaki acısını işleyen lirik bir trajedidir.'),
  ('Türk edebiyatında "absürt (uyumsuz) tiyatro"nun en önemli örneklerinden biri kabul edilen "Canlı Maymun Lokantası" dışında, Melih Cevdet Anday\'ın aynı anlayışla yazdığı ünlü oyunu hangisidir?', 'Mikado\'nun Çöpleri', ['Asiye Nasıl Kurtulur', 'Zengin Mutfağı', 'Yedi Kocalı Hürmüz'], 'Melih Cevdet Anday; "İçerdekiler" adlı psikolojik-politik oyununun yanı sıra "Mikado\'nun Çöpleri", "Dikkat Köpek Var" ve "Ölüler Konuşmak İster" ile uyumsuz/felsefi tiyatronun seçkin örneklerini vermiştir.'),
  ('Vasıf Öngören\'in 1970\'li yıllardaki işçi hareketlerini (15-16 Haziran olaylarını) büyük bir köşkün mutfağında çalışan aşçı Lütfü Usta ve hizmetlilerin gözünden anlattığı epik oyunu hangisidir?', 'Zengin Mutfağı', ['Almanya Defteri', 'Ayak Bacak Fabrikası', 'Rumuz Goncagül'], 'Şener Şen\'in hem tiyatroda hem sinemada Lütfü Usta rolüyle ölümsüzleştirdiği "Zengin Mutfağı", sınıfsal uyanışı ve faşizmin tırmanışını mutfak mekanı üzerinden anlatır.'),
  ('Toplumcu gerçekçi Türk tiyatrosunun öncü yapıtlarından olan ve derebeylik-bürokrasi iş birliğiyle halka dağıtılan bozuk tohumların köylüyü kötürüm bırakmasını işleyen "Ayak Bacak Fabrikası" kimin eseridir?', 'Sermet Çağan', ['Vasıf Öngören', 'Cahit Atay', 'Erol Toy'], 'Sermet Çağan\'ın 1963\'te yazdığı ve uluslararası festivallerde ödüller kazanan "Ayak Bacak Fabrikası", Türkiye\'de politik-epik tiyatronun dönüm noktalarından biridir.'),
  ('Cumhuriyet Dönemi\'nde "Sular Aydınlanıyordu" ve "Sevdican" gibi şiirsel-lirik oyunlarıyla kadın duyarlılığını ve toplumsal dayanışmayı sahneye taşıyan öykü ve oyun yazarı kimdir?', 'Nezihe Meriç', ['Pınar Kür', 'Füruzan', 'Tomris Uyar'], 'Cumhuriyet Dönemi\'nin ilk kadın öykücülerinden Nezihe Meriç, "Sular Aydınlanıyordu" oyununda dokuz kadının monologları üzerinden Türkiye\'nin toplumsal manzarasını çizmiştir.'),
  ('Garip şiirinin öncülerinden olup "Birtakım İnsanlar", "Kadınlar Arasında" (Çil Horoz) ve "Atlarla Filler" gibi oyunlarıyla tiyatro türünde de eserler veren şair kimdir?', 'Oktay Rifat', ['Orhan Veli Kanık', 'Cemal Süreya', 'Edip Cansever'], 'Oktay Rifat; "Kadınlar Arasında", "Oyun İçinde Oyun", "Zabit Fatma\'nın Kuzusu" ve "Yağmur Sıkıntısı" gibi oyunlarıyla birey-toplum ilişkilerini sahneye taşımıştır.'),
  ('Özellikle radyo tiyatrosu alanında Türk edebiyatının en özgün metinlerini üreten; "Yıldızlara Bakmak", "Gece Aşevi" ve "Üç Turunçlar" adlı radyo oyunlarının şair yazarı kimdir?', 'Behçet Necatigil', ['Ziya Osman Saba', 'Fazıl Hüsnü Dağlarca', 'İlhan Berk'], '"Evler şairi" Behçet Necatigil, radyo oyununu bağımsız ve yüksek nitelikli bir edebi tür seviyesine çıkarmış, şiirsel iç konuşmalarla dar gelirli insanların iç dünyasını yansıtmıştır.'),
  ('1970 sonrası Türk tiyatrosunda "Şerefiye", "Zemberek" ve "Mutlu Günler" gibi oyunların yanı sıra "Kargalar" ve "Saygılı Yosma" sahnelemeleriyle tanınan toplumcu yazar ve yönetmen kimdir?', 'Başar Sabuncu', ['Ergin Orbey', 'Yücel Erten', 'Rutkay Aziz'], 'Başar Sabuncu; "Şerefiye", "Çark", "Zemberek" ve "Kaldırım Serçesi" gibi eserleriyle hem oyun yazarlığı hem de çağdaş sahne yönetmenliği alanında iz bırakmıştır.'),
  ('1980 sonrası Türk tiyatrosunda ince entelektüel mizahı, dil oyunları ve modern insanın iletişimsizliğini işleyen; "Limon", "Kadın İstasyonu" ve "Yangın Yerinde Orkideler" adlı oyunların yazarı kimdir?', 'Memet Baydur', ['Murathan Mungan', 'Tuncer Cücenoğlu', 'Özen Yula'], 'Memet Baydur; "Cumhuriyet Kızı", "Limon", "Düdüklüde Kıymalı Bamya" ve "Kamyon" gibi oyunlarıyla yakın dönem Türk tiyatrosuna çağdaş ve evrensel bir soluk getirmiştir.'),
  ('Mezopotamya kültüründen beslenen "Mezopotamya Üçlemesi"ni ("Mahmud ile Yezida", "Taziye", "Geyikler Lanetler") şiirsel ve ritüelistik bir sahne diliyle kaleme alan yazar kimdir?', 'Murathan Mungan', ['Orhan Asena', 'Güngör Dilmen', 'Yılmaz Onay'], 'Murathan Mungan, "Mahmud ile Yezida", "Taziye" ve "Geyikler Lanetler"den oluşan Mezopotamya Üçlemesi\'nde töre, kader, kan davası ve mitolojik motifleri yüksek bir şiirsellikle birleştirmiştir.'),
  ('1960 sonrası Türk tiyatrosunun 1923-1950 dönemine kıyasla hem içerik hem de biçim açısından gösterdiği en önemli sıçrama aşağıdakilerden hangisidir?', 'Gecekondu, göç, sınıf çatışması ve töre gibi keskin toplumsal sorunların epik, absürt ve geleneksel açık biçim sentezleriyle sahneye taşınması', ['Yerli oyun yazarlığının tamamen terk edilerek yalnızca Fransız bulvar komedyalarının çevirisiyle yetinilmesi', 'Tarihsel konuların işlenmesinin yasaklanarak yalnızca tek perdelik çocuk oyunlarının sahnelenmesine izin verilmesi', 'Anadolu coğrafyasının sahneden çıkarılıp yalnızca İstanbul yalılarındaki bireysel aşk üçgenlerinin ele alınması'], '1960 sonrasında Haldun Taner, Güngör Dilmen, Orhan Asena, Turan Oflazoğlu, Turgut Özakman, Cahit Atay ve Vasıf Öngören gibi yazarlarla Türk tiyatrosu altın çağını yaşamış; hem toplumsal eleştiri derinleşmiş hem ulusal sahne biçimi arayışları meyve vermiştir.'),
  ('Abdülhak Hamit Tarhan\'ın İngilizlerin Hindistan\'daki sömürge yönetimini ve İngiliz subayı Thompson ile Hintli kız Surucuyi arasındaki imkansız aşkı işlediği eseri hangisidir?', 'Duhter-i Hindu', ['Macera-yı Aşk', 'Sabr u Sebat', 'İçli Kız'], '1876\'da yayımlanan "Duhter-i Hindu" (Hint Kızı), Abdülhak Hamit\'in egzotik mekanlara ve sömürgecilik eleştirisine yöneldiği önemli bir dramıdır.'),
  ('Tanzimat Dönemi\'nde klasik Fransız edebiyatına ve Moliere komedyalarına bağlı kalarak "Kıskançlar", "İyi Saatinde Olsunlar" değil; hece ölçüsüne ve konuşma diline özen gösteren "İlk Sevgi" ve "Kısmet Değilmiş" oyunlarını Bursa\'da yazan vali-yazar kimdir?', 'Feraizcizade Mehmet Şakir', ['Direktör Ali Bey', 'Ebüzziya Tevfik', 'Manastırlı Rıfat'], 'Bursa\'da Ahmet Vefik Paşa\'nın tiyatro çevresinde yetişen Feraizcizade Mehmet Şakir; "Evhami", "İcab-ı Gurur" ve "İlk Sevgi" gibi telif komedyaları ve noktalama işaretlerine verdiği önemle tanınır.'),
  ('Asaf Çiyiltepe tarafından 1963 yılında Ankara\'da kurulan ve "Ayak Bacak Fabrikası", "72. Koğuş", "Durdurun Dünyayı İnecek Var" gibi oyunlarla toplumcu tiyatro geleneğini sürdüren kurum hangisidir?', 'Ankara Sanat Tiyatrosu', ['Devlet Tiyatroları', 'Küçük Sahne', 'Meydan Sahnesi'], 'Kısaca AST olarak bilinen Ankara Sanat Tiyatrosu, Asaf Çiyiltepe\'nin kuruluş vizyonuyla Türkiye\'de devrimci ve toplumcu sanat anlayışının kalesi olmuştur.'),
  ('Şinasi\'nin "Şair Evlenmesi" (1860) ile Necati Cumalı\'nın "Nalınlar" veya Turgut Özakman\'ın "Töre" gibi yüz yıl sonra yazılan oyunları karşılaştırıldığında Türk tiyatrosundaki hangi tematik süreklilik dikkat çeker?', 'Aile kurumu, evlilik gelenekleri ve toplumsal töre baskısının bireyin özgür iradesi üzerindeki etkisinin her dönemde güncelliğini koruması', ['Tüm oyunların yalnızca sarayda yaşayan vezir çocuklarının eğitim sorunlarını aruz ölçüsüyle anlatması', 'Kadın karakterlerin tiyatro metinlerinde hiçbir zaman konuşma hakkına sahip olmadan sessiz kalması', 'Yabancı dildeki Fransızca kelimelerin oranının Cumhuriyet\'e doğru gidildikçe sürekli artış göstermesi'], 'Tanzimat\'taki görücü usulü evlilik eleştirisinden ("Şair Evlenmesi", "Zavallı Çocuk") Cumhuriyet tiyatrosundaki başlık parası ve töre eleştirilerine uzanan çizgide bireyin ve özellikle kadının özgür iradesi temel izleklerden biri olmuştur.'),
  ('Muhsin Ertuğrul\'un 1951 yılında İstanbul\'da özel bir girişim olarak kurduğu ve Türk tiyatrosunda yeni bir oyuncu ve seyirci kuşağı yetiştiren "Küçük Sahne" topluluğunun tiyatro tarihimizdeki önemi nedir?', 'Devlet ve Şehir tiyatroları dışında modern, sanatsal düzeyi yüksek özel tiyatro hareketinin Türkiye\'de canlanmasına öncülük etmesi', ['Osmanlı\'da ilk kez yabancı dilde İtalyan operalarının sahnelendiği saray tiyatrosunu açması', 'Köy enstitülerinde yalnızca tarım dersleri verilmesini sağlayan eğitim müfredatını hazırlaması', 'Türkiye\'deki tüm tiyatro binalarının sinema salonuna dönüştürülmesi kararını uygulaması'], 'Muhsin Ertuğrul\'un Beyoğlu Atlas Sineması\'nın üst katında kurduğu "Küçük Sahne", Münir Özkul, Sadri Alışık, Cahit Irgat, Şükran Güngör, Haldun Dormen gibi ustaların yetiştiği modern özel tiyatro ocağı olmuştur.'),
  ('Cahit Atay\'ın "Pusuda" adlı oyununda kasaba ağası Yılanoğlu\'nun kışkırtmasıyla kasabaya dönen aydın genç Kamuran\'ı vurmak için pusu kuran saf köylü karakter kimdir?', 'Yaşar', ['Dursun', 'Cabbar', 'Murtaza'], 'Yılanoğlu\'nun kışkırtmasıyla tüfek kuşanıp pusuya yatan saf köylü Yaşar, vuracağı aydın genç Kamuran ile sohbet edince gerçeği fark eder ancak kaza kurşunuyla trajedi yaşanır.'),
  ('Türk edebiyatında "absürt (uyumsuz) tiyatro"nun en önemli örneklerinden biri kabul edilen ve iki erkek karakterin uzun diyaloğuna dayanan Melih Cevdet Anday oyunu hangisidir?', 'Mikado\'nun Çöpleri', ['Asiye Nasıl Kurtulur', 'Zengin Mutfağı', 'Yedi Kocalı Hürmüz'], 'Melih Cevdet Anday; "İçerdekiler" adlı psikolojik-politik oyununun yanı sıra "Mikado\'nun Çöpleri", "Dikkat Köpek Var" ve "Ölüler Konuşmak İster" ile uyumsuz/felsefi tiyatronun seçkin örneklerini vermiştir.'),
  ('Bursa\'da Ahmet Vefik Paşa\'nın kültür çevresinde yetişen, konuşma diline ve noktalama işaretlerine büyük özen göstererek "Evhami", "İlk Sevgi" ve "İcab-ı Gurur" komedyalarını yazan Tanzimat yazarı kimdir?', 'Feraizcizade Mehmet Şakir', ['Direktör Ali Bey', 'Ebüzziya Tevfik', 'Manastırlı Rıfat'], 'Feraizcizade Mehmet Şakir, Moliere ve geleneksel tiyatrodan yararlanarak telif komedyalar yazmış ve sahne dilinin doğallaşmasına katkıda bulunmuştur.'),
  ('Muallim Naci\'nin Endülüs Emevi Devleti\'nin son dönemlerinde Gırnata\'nın düşüşü sırasında İspanyollara teslim olmayı reddederek şehit düşen komutanı anlattığı tarihsel tiyatrosu hangisidir?', 'Musa bin Ebi\'l-Gazan yahut Hamiyet', ['Besa yahut Ahde Vefa', 'Celaleddin Harzemşah', 'Atala yahut Amerikan Vahşileri'], 'Muallim Naci\'nin vatanseverlik ve kahramanlık duygularını işlediği "Musa bin Ebi\'l-Gazan yahut Hamiyet" adlı eseri Tanzimat Dönemi tarihsel tiyatrosunun dikkat çekici örneklerindendir.'),
];
